window.GAOKAO_ANSWERS=Object.assign(window.GAOKAO_ANSWERS||{},{"triangle-big-001":{"final":"（I）\\(C=\\frac{\\pi}{3}\\)；（II）\\(\\triangle ABC\\) 的周长为 \\(5+\\sqrt{7}\\)。","solution":"（I）由正弦定理，设外接圆半径为 \\(R\\)，则 \\(a=2R\\sin A,\\ b=2R\\sin B,\\ c=2R\\sin C\\)。\n把 \\(a\\cos B+b\\cos A\\) 化为 \\(2R(\\sin A\\cos B+\\sin B\\cos A)=2R\\sin(A+B)\\)。\n因为 \\(A+B=\\pi-C\\)，所以 \\(\\sin(A+B)=\\sin C\\)，于是 \\(a\\cos B+b\\cos A=2R\\sin C=c\\)（射影定理）。\n代回已知条件 \\(2\\cos C(a\\cos B+b\\cos A)=c\\)，得 \\(2c\\cos C=c\\)。\n因为 \\(c>0\\)，两边约去 \\(c\\) 得 \\(\\cos C=\\frac{1}{2}\\)。\n又 \\(C\\in(0,\\pi)\\)，故 \\(C=\\frac{\\pi}{3}\\)。\n（II）由面积公式 \\(S=\\frac{1}{2}ab\\sin C=\\frac{1}{2}ab\\cdot\\frac{\\sqrt{3}}{2}=\\frac{\\sqrt{3}}{4}ab\\)。\n由 \\(S=\\frac{3\\sqrt{3}}{2}\\) 得 \\(\\frac{\\sqrt{3}}{4}ab=\\frac{3\\sqrt{3}}{2}\\)，即 \\(ab=6\\)。\n由余弦定理 \\(c^{2}=a^{2}+b^{2}-2ab\\cos C=a^{2}+b^{2}-ab=(a+b)^{2}-3ab\\)。\n代入 \\(c=\\sqrt{7},\\ ab=6\\) 得 \\(7=(a+b)^{2}-18\\)，所以 \\((a+b)^{2}=25\\)，即 \\(a+b=5\\)。\n故周长为 \\(a+b+c=5+\\sqrt{7}\\)。","scoring":[{"text":"用正弦定理把 \\(a\\cos B+b\\cos A\\) 化为 \\(c\\)，代入得 \\(2c\\cos C=c\\)","points":4},{"text":"由 \\(c>0\\) 得 \\(\\cos C=\\frac{1}{2}\\)，结合 \\(C\\in(0,\\pi)\\) 得 \\(C=\\frac{\\pi}{3}\\)","points":2},{"text":"用面积公式 \\(S=\\frac{1}{2}ab\\sin C\\) 求出 \\(ab=6\\)","points":3},{"text":"用余弦定理得 \\((a+b)^{2}=25\\)，即 \\(a+b=5\\)","points":2},{"text":"得出周长 \\(5+\\sqrt{7}\\)","points":1}]},"triangle-big-002":{"final":"（I）\\(B=\\frac{\\pi}{4}\\)；（II）\\(\\sqrt{2}\\cos A+\\cos C\\) 的最大值为 \\(1\\)，此时 \\(A=C=\\frac{\\pi}{4}\\)。","solution":"（I）由余弦定理 \\(\\cos B=\\frac{a^{2}+c^{2}-b^{2}}{2ac}\\)。\n已知 \\(a^{2}+c^{2}=b^{2}+\\sqrt{2}ac\\)，即 \\(a^{2}+c^{2}-b^{2}=\\sqrt{2}ac\\)。\n代入得 \\(\\cos B=\\frac{\\sqrt{2}ac}{2ac}=\\frac{\\sqrt{2}}{2}\\)。\n又 \\(B\\in(0,\\pi)\\)，故 \\(B=\\frac{\\pi}{4}\\)。\n（II）由 \\(A+B+C=\\pi\\) 及 \\(B=\\frac{\\pi}{4}\\) 得 \\(C=\\frac{3\\pi}{4}-A\\)，其中 \\(0<A<\\frac{3\\pi}{4}\\)。\n于是 \\(\\sqrt{2}\\cos A+\\cos C=\\sqrt{2}\\cos A+\\cos\\left(\\frac{3\\pi}{4}-A\\right)\\)。\n用差角公式展开：\\(\\cos\\left(\\frac{3\\pi}{4}-A\\right)=\\cos\\frac{3\\pi}{4}\\cos A+\\sin\\frac{3\\pi}{4}\\sin A=-\\frac{\\sqrt{2}}{2}\\cos A+\\frac{\\sqrt{2}}{2}\\sin A\\)。\n所以原式 \\(=\\sqrt{2}\\cos A-\\frac{\\sqrt{2}}{2}\\cos A+\\frac{\\sqrt{2}}{2}\\sin A=\\frac{\\sqrt{2}}{2}(\\sin A+\\cos A)\\)。\n再用辅助角公式得 \\(\\frac{\\sqrt{2}}{2}(\\sin A+\\cos A)=\\sin\\left(A+\\frac{\\pi}{4}\\right)\\)。\n因为 \\(0<A<\\frac{3\\pi}{4}\\)，所以 \\(\\frac{\\pi}{4}<A+\\frac{\\pi}{4}<\\pi\\)，从而 \\(\\sin\\left(A+\\frac{\\pi}{4}\\right)\\le 1\\)。\n当 \\(A+\\frac{\\pi}{4}=\\frac{\\pi}{2}\\) 即 \\(A=\\frac{\\pi}{4}\\) 时取到等号，此时 \\(C=\\frac{\\pi}{2}\\)，三角形存在。\n故最大值为 \\(1\\)。","scoring":[{"text":"用余弦定理及已知条件得 \\(\\cos B=\\frac{\\sqrt{2}}{2}\\)","points":2},{"text":"结合 \\(B\\in(0,\\pi)\\) 得 \\(B=\\frac{\\pi}{4}\\)","points":2},{"text":"由 \\(C=\\frac{3\\pi}{4}-A\\) 把待求式化为只含 \\(A\\) 的式子并用差角公式展开","points":3},{"text":"用辅助角公式化为 \\(\\sin\\left(A+\\frac{\\pi}{4}\\right)\\)","points":3},{"text":"求出最大值 \\(1\\) 并指出取等条件 \\(A=\\frac{\\pi}{4}\\)","points":2}]},"triangle-big-003":{"final":"（I）证明得 \\(A=2B\\)（过程见下）；（II）\\(A=\\frac{\\pi}{2}\\)。","solution":"（I）由正弦定理 \\(\\frac{a}{\\sin A}=\\frac{b}{\\sin B}=\\frac{c}{\\sin C}=2R\\)，设 \\(a=2R\\sin A,\\ b=2R\\sin B,\\ c=2R\\sin C\\)。\n把 \\(b+c=2a\\cos B\\) 两边同除以 \\(2R\\)，得 \\(\\sin B+\\sin C=2\\sin A\\cos B\\)。\n因为 \\(C=\\pi-(A+B)\\)，所以 \\(\\sin C=\\sin(A+B)=\\sin A\\cos B+\\cos A\\sin B\\)。\n代入上式得 \\(\\sin B+\\sin A\\cos B+\\cos A\\sin B=2\\sin A\\cos B\\)。\n移项整理得 \\(\\sin B+\\cos A\\sin B=\\sin A\\cos B\\)，即 \\(\\sin B(1+\\cos A)=\\sin A\\cos B\\)。\n因为 \\(\\sin B>0,\\ 1+\\cos A>0,\\ \\sin A>0\\)，由上式知 \\(\\cos B>0\\)，故 \\(B\\in\\left(0,\\frac{\\pi}{2}\\right)\\)。\n两边同除以 \\(\\cos B(1+\\cos A)\\) 得 \\(\\frac{\\sin B}{\\cos B}=\\frac{\\sin A}{1+\\cos A}\\)，即 \\(\\tan B=\\frac{\\sin A}{1+\\cos A}\\)。\n由二倍角公式 \\(\\sin A=2\\sin\\frac{A}{2}\\cos\\frac{A}{2}\\)，\\(1+\\cos A=2\\cos^{2}\\frac{A}{2}\\)，得 \\(\\frac{\\sin A}{1+\\cos A}=\\tan\\frac{A}{2}\\)。\n所以 \\(\\tan B=\\tan\\frac{A}{2}\\)。\n又 \\(0<B<\\frac{\\pi}{2}\\)，\\(0<\\frac{A}{2}<\\frac{\\pi}{2}\\)，而正切函数在 \\(\\left(0,\\frac{\\pi}{2}\\right)\\) 上单调递增，故 \\(B=\\frac{A}{2}\\)。\n即 \\(A=2B\\)。\n（II）因为 \\(S=\\frac{1}{2}ac\\sin B\\)，由 \\(S=\\frac{a^{2}}{4}\\) 得 \\(\\frac{1}{2}ac\\sin B=\\frac{a^{2}}{4}\\)。\n因为 \\(a>0\\)，整理得 \\(2c\\sin B=a\\)。\n由正弦定理 \\(\\frac{a}{c}=\\frac{\\sin A}{\\sin B}\\)，把 \\(a=2c\\sin B\\) 代入得 \\(\\frac{\\sin A}{\\sin B}=2\\sin B\\)，即 \\(\\sin A=2\\sin^{2}B\\)。\n由（I）\\(A=2B\\)，故 \\(\\sin A=\\sin 2B=2\\sin B\\cos B\\)，代入得 \\(2\\sin B\\cos B=2\\sin^{2}B\\)。\n因为 \\(\\sin B>0\\)，约去 \\(2\\sin B\\) 得 \\(\\cos B=\\sin B\\)，即 \\(\\tan B=1\\)。\n由（I）知 \\(B\\in\\left(0,\\frac{\\pi}{2}\\right)\\)，故 \\(B=\\frac{\\pi}{4}\\)，从而 \\(A=2B=\\frac{\\pi}{2}\\)。","scoring":[{"text":"用正弦定理把 \\(b+c=2a\\cos B\\) 化为 \\(\\sin B+\\sin C=2\\sin A\\cos B\\)","points":2},{"text":"用 \\(\\sin C=\\sin(A+B)\\) 展开，整理得 \\(\\sin B(1+\\cos A)=\\sin A\\cos B\\)","points":3},{"text":"化为 \\(\\tan B=\\tan\\frac{A}{2}\\)，说明 \\(B,\\frac{A}{2}\\) 的范围，得 \\(A=2B\\)","points":3},{"text":"由面积公式与正弦定理得 \\(\\sin A=2\\sin^{2}B\\)","points":2},{"text":"结合 \\(A=2B\\) 得 \\(B=\\frac{\\pi}{4}\\)，从而 \\(A=\\frac{\\pi}{2}\\)","points":2}]},"triangle-big-004":{"final":"（1）\\(\\sin B\\sin C=\\frac{2}{3}\\)；（2）\\(\\triangle ABC\\) 的周长为 \\(3+\\sqrt{33}\\)。","solution":"（1）由面积公式 \\(S=\\frac{1}{2}bc\\sin A\\)，又已知 \\(S=\\frac{a^{2}}{3\\sin A}\\)，得 \\(\\frac{1}{2}bc\\sin A=\\frac{a^{2}}{3\\sin A}\\)。\n整理得 \\(bc\\sin^{2}A=\\frac{2}{3}a^{2}\\)。\n由正弦定理 \\(a=2R\\sin A,\\ b=2R\\sin B,\\ c=2R\\sin C\\)，代入得 \\(4R^{2}\\sin B\\sin C\\cdot\\sin^{2}A=\\frac{2}{3}\\cdot 4R^{2}\\sin^{2}A\\)。\n因为 \\(R>0,\\ \\sin A>0\\)，两边约去 \\(4R^{2}\\sin^{2}A\\) 得 \\(\\sin B\\sin C=\\frac{2}{3}\\)。\n（2）由 \\(6\\cos B\\cos C=1\\) 得 \\(\\cos B\\cos C=\\frac{1}{6}\\)。\n所以 \\(\\cos(B+C)=\\cos B\\cos C-\\sin B\\sin C=\\frac{1}{6}-\\frac{2}{3}=-\\frac{1}{2}\\)。\n因为 \\(B+C\\in(0,\\pi)\\)，故 \\(B+C=\\frac{2\\pi}{3}\\)，从而 \\(A=\\pi-(B+C)=\\frac{\\pi}{3}\\)。\n由 \\(S=\\frac{a^{2}}{3\\sin A}\\)，代入 \\(a=3,\\ \\sin A=\\frac{\\sqrt{3}}{2}\\) 得 \\(S=\\frac{9}{3\\times\\frac{\\sqrt{3}}{2}}=\\frac{6}{\\sqrt{3}}=2\\sqrt{3}\\)。\n又 \\(S=\\frac{1}{2}bc\\sin A\\)，即 \\(\\frac{1}{2}bc\\cdot\\frac{\\sqrt{3}}{2}=2\\sqrt{3}\\)，解得 \\(bc=8\\)。\n由余弦定理 \\(a^{2}=b^{2}+c^{2}-2bc\\cos A=b^{2}+c^{2}-bc=(b+c)^{2}-3bc\\)。\n代入 \\(a=3,\\ bc=8\\) 得 \\(9=(b+c)^{2}-24\\)，即 \\((b+c)^{2}=33\\)，所以 \\(b+c=\\sqrt{33}\\)。\n故周长为 \\(a+b+c=3+\\sqrt{33}\\)。","scoring":[{"text":"由面积公式与 \\(S=\\frac{a^{2}}{3\\sin A}\\) 建立关于 \\(bc\\sin^{2}A\\) 的等式","points":2},{"text":"用正弦定理边化角，约元得 \\(\\sin B\\sin C=\\frac{2}{3}\\)","points":3},{"text":"由 \\(\\cos(B+C)=\\cos B\\cos C-\\sin B\\sin C\\) 得 \\(\\cos(B+C)=-\\frac{1}{2}\\)，从而 \\(A=\\frac{\\pi}{3}\\)","points":4},{"text":"求出 \\(bc=8\\)","points":1},{"text":"用余弦定理求 \\(b+c=\\sqrt{33}\\)，得周长 \\(3+\\sqrt{33}\\)","points":2}]},"triangle-big-005":{"final":"（1）\\(\\cos B=\\frac{15}{17}\\)；（2）\\(b=2\\)。","solution":"（1）因为 \\(A+B+C=\\pi\\)，所以 \\(\\sin(A+C)=\\sin(\\pi-B)=\\sin B\\)。\n由半角公式 \\(\\sin^{2}\\frac{B}{2}=\\frac{1-\\cos B}{2}\\)，已知条件化为 \\(\\sin B=8\\times\\frac{1-\\cos B}{2}=4(1-\\cos B)\\)。\n两边平方得 \\(\\sin^{2}B=16(1-\\cos B)^{2}\\)，即 \\(1-\\cos^{2}B=16(1-\\cos B)^{2}\\)。\n左边因式分解得 \\((1-\\cos B)(1+\\cos B)=16(1-\\cos B)^{2}\\)。\n因为 \\(B\\in(0,\\pi)\\)，所以 \\(\\cos B\\ne 1\\)，即 \\(1-\\cos B\\ne 0\\)。\n两边约去 \\(1-\\cos B\\) 得 \\(1+\\cos B=16(1-\\cos B)\\)。\n解得 \\(17\\cos B=15\\)，即 \\(\\cos B=\\frac{15}{17}\\)。\n检验：此时 \\(\\sin B=4\\left(1-\\frac{15}{17}\\right)=\\frac{8}{17}>0\\)，与原方程相符。\n（2）由（1）得 \\(\\sin B=\\sqrt{1-\\left(\\frac{15}{17}\\right)^{2}}=\\frac{8}{17}\\)。\n由面积公式 \\(S=\\frac{1}{2}ac\\sin B=2\\)，得 \\(\\frac{1}{2}ac\\cdot\\frac{8}{17}=2\\)，即 \\(ac=\\frac{17}{2}\\)。\n由余弦定理 \\(b^{2}=a^{2}+c^{2}-2ac\\cos B=(a+c)^{2}-2ac-2ac\\cos B=(a+c)^{2}-2ac(1+\\cos B)\\)。\n代入 \\(a+c=6,\\ ac=\\frac{17}{2},\\ \\cos B=\\frac{15}{17}\\) 得 \\(b^{2}=36-2\\times\\frac{17}{2}\\times\\frac{32}{17}=36-32=4\\)。\n所以 \\(b=2\\)。","scoring":[{"text":"用 \\(\\sin(A+C)=\\sin B\\) 与半角公式把条件化为 \\(\\sin B=4(1-\\cos B)\\)","points":3},{"text":"平方后因式分解、约去 \\(1-\\cos B\\)，求得 \\(\\cos B=\\frac{15}{17}\\)","points":3},{"text":"求 \\(\\sin B=\\frac{8}{17}\\)，由面积公式得 \\(ac=\\frac{17}{2}\\)","points":3},{"text":"余弦定理变形求 \\(b^{2}=4\\)，得 \\(b=2\\)","points":3}]},"triangle-big-006":{"final":"（1）\\(c=4\\)；（2）\\(\\triangle ABD\\) 的面积为 \\(\\sqrt{3}\\)。","solution":"（1）由 \\(\\sin A+\\sqrt{3}\\cos A=0\\) 得 \\(\\tan A=-\\sqrt{3}\\)。\n因为 \\(A\\in(0,\\pi)\\)，故 \\(A=\\frac{2\\pi}{3}\\)。\n由余弦定理 \\(a^{2}=b^{2}+c^{2}-2bc\\cos A\\)，代入 \\(a=2\\sqrt{7},\\ b=2,\\ \\cos A=-\\frac{1}{2}\\) 得 \\(28=4+c^{2}+2c\\)。\n整理得 \\(c^{2}+2c-24=0\\)，即 \\((c+1)^{2}=25\\)，解得 \\(c=4\\) 或 \\(c=-6\\)。\n因为 \\(c>0\\)，故 \\(c=4\\)。\n（2）在 \\(\\triangle ABC\\) 中，由余弦定理 \\(\\cos C=\\frac{a^{2}+b^{2}-c^{2}}{2ab}=\\frac{28+4-16}{2\\times 2\\sqrt{7}\\times 2}=\\frac{2}{\\sqrt{7}}\\)。\n因为 \\(C\\in(0,\\pi)\\)，所以 \\(\\sin C=\\sqrt{1-\\frac{4}{7}}=\\frac{\\sqrt{3}}{\\sqrt{7}}\\)，从而 \\(\\tan C=\\frac{\\sin C}{\\cos C}=\\frac{\\sqrt{3}}{2}\\)。\n因为 \\(AD\\perp AC\\)，所以在 \\(Rt\\triangle ACD\\) 中 \\(\\tan C=\\frac{AD}{AC}\\)。\n于是 \\(AD=AC\\cdot\\tan C=2\\times\\frac{\\sqrt{3}}{2}=\\sqrt{3}\\)。\n又 \\(\\angle BAD=\\angle BAC-\\angle DAC=\\frac{2\\pi}{3}-\\frac{\\pi}{2}=\\frac{\\pi}{6}\\)。\n所以 \\(S_{\\triangle ABD}=\\frac{1}{2}\\cdot AB\\cdot AD\\cdot\\sin\\angle BAD=\\frac{1}{2}\\times 4\\times\\sqrt{3}\\times\\frac{1}{2}=\\sqrt{3}\\)。","scoring":[{"text":"由 \\(\\sin A+\\sqrt{3}\\cos A=0\\) 求得 \\(A=\\frac{2\\pi}{3}\\)","points":2},{"text":"用余弦定理列方程并解得 \\(c=4\\)（舍去负值）","points":3},{"text":"求 \\(\\cos C=\\frac{2}{\\sqrt{7}}\\)，进而 \\(\\tan C=\\frac{\\sqrt{3}}{2}\\)","points":2},{"text":"在 \\(Rt\\triangle ACD\\) 中求 \\(AD=\\sqrt{3}\\)","points":2},{"text":"求 \\(\\angle BAD=\\frac{\\pi}{6}\\)，用面积公式得 \\(S_{\\triangle ABD}=\\sqrt{3}\\)","points":3}]},"triangle-big-007":{"final":"（I）\\(\\cos A=-\\frac{\\sqrt{5}}{5}\\)；（II）\\(\\sin(2B-A)=-\\frac{2\\sqrt{5}}{5}\\)。","solution":"（I）由正弦定理 \\(\\frac{a}{\\sin A}=\\frac{b}{\\sin B}=2R\\)，得 \\(a=2R\\sin A,\\ b=2R\\sin B\\)。\n代入 \\(a\\sin A=4b\\sin B\\) 得 \\(2R\\sin^{2}A=8R\\sin^{2}B\\)，即 \\(\\sin^{2}A=4\\sin^{2}B\\)。\n因为 \\(\\sin A>0,\\ \\sin B>0\\)，所以 \\(\\sin A=2\\sin B\\)，再由正弦定理得 \\(a=2b\\)。\n由余弦定理 \\(a^{2}-b^{2}-c^{2}=-2bc\\cos A\\)，代入 \\(ac=\\sqrt{5}(a^{2}-b^{2}-c^{2})\\) 得 \\(ac=-2\\sqrt{5}bc\\cos A\\)。\n因为 \\(bc>0\\)，两边约去 \\(bc\\) 得 \\(a=-2\\sqrt{5}b\\cos A\\)。\n所以 \\(\\cos A=-\\frac{a}{2\\sqrt{5}b}=-\\frac{2b}{2\\sqrt{5}b}=-\\frac{1}{\\sqrt{5}}=-\\frac{\\sqrt{5}}{5}\\)。\n（II）因为 \\(A\\in(0,\\pi)\\) 且 \\(\\cos A<0\\)，所以 \\(\\sin A=\\sqrt{1-\\frac{1}{5}}=\\frac{2}{\\sqrt{5}}=\\frac{2\\sqrt{5}}{5}\\)。\n由 \\(a=2b\\) 及正弦定理得 \\(\\sin A=2\\sin B\\)，所以 \\(\\sin B=\\frac{1}{2}\\sin A=\\frac{1}{\\sqrt{5}}=\\frac{\\sqrt{5}}{5}\\)。\n因为 \\(A\\) 为钝角，所以 \\(B\\) 必为锐角，\\(\\cos B=\\sqrt{1-\\frac{1}{5}}=\\frac{2}{\\sqrt{5}}=\\frac{2\\sqrt{5}}{5}\\)。\n由二倍角公式 \\(\\sin 2B=2\\sin B\\cos B=2\\times\\frac{1}{\\sqrt{5}}\\times\\frac{2}{\\sqrt{5}}=\\frac{4}{5}\\)，\\(\\cos 2B=1-2\\sin^{2}B=1-\\frac{2}{5}=\\frac{3}{5}\\)。\n所以 \\(\\sin(2B-A)=\\sin 2B\\cos A-\\cos 2B\\sin A=\\frac{4}{5}\\times\\left(-\\frac{1}{\\sqrt{5}}\\right)-\\frac{3}{5}\\times\\frac{2}{\\sqrt{5}}\\)。\n即 \\(\\sin(2B-A)=-\\frac{4}{5\\sqrt{5}}-\\frac{6}{5\\sqrt{5}}=-\\frac{10}{5\\sqrt{5}}=-\\frac{2}{\\sqrt{5}}=-\\frac{2\\sqrt{5}}{5}\\)。","scoring":[{"text":"由正弦定理把 \\(a\\sin A=4b\\sin B\\) 化为 \\(\\sin A=2\\sin B\\)，得 \\(a=2b\\)","points":3},{"text":"由余弦定理把 \\(a^{2}-b^{2}-c^{2}\\) 写成 \\(-2bc\\cos A\\)，结合已知条件求 \\(\\cos A=-\\frac{\\sqrt{5}}{5}\\)","points":3},{"text":"求 \\(\\sin A,\\ \\sin B,\\ \\cos B\\)（注意 \\(A\\) 为钝角、\\(B\\) 为锐角）","points":3},{"text":"用二倍角公式求 \\(\\sin 2B,\\ \\cos 2B\\)，再用差角公式得 \\(\\sin(2B-A)=-\\frac{2\\sqrt{5}}{5}\\)","points":3}]},"triangle-big-008":{"final":"（1）\\(\\cos\\angle ADB=\\frac{\\sqrt{23}}{5}\\)；（2）\\(BC=5\\)。","solution":"（1）在 \\(\\triangle ABD\\) 中，由正弦定理 \\(\\frac{BD}{\\sin\\angle A}=\\frac{AB}{\\sin\\angle ADB}\\)。\n代入 \\(BD=5,\\ AB=2,\\ \\angle A=45^{\\circ}\\)，得 \\(\\frac{5}{\\frac{\\sqrt{2}}{2}}=\\frac{2}{\\sin\\angle ADB}\\)。\n解得 \\(\\sin\\angle ADB=\\frac{\\sqrt{2}}{5}\\)。\n因为 \\(AB=2<BD=5\\)，三角形中大边对大角，所以 \\(\\angle ADB<\\angle A=45^{\\circ}\\)，即 \\(\\angle ADB\\) 为锐角。\n故 \\(\\cos\\angle ADB=\\sqrt{1-\\sin^{2}\\angle ADB}=\\sqrt{1-\\frac{2}{25}}=\\frac{\\sqrt{23}}{5}\\)。\n（2）因为 \\(\\angle ADC=90^{\\circ}\\)，所以 \\(\\angle BDC=90^{\\circ}-\\angle ADB\\)。\n于是 \\(\\cos\\angle BDC=\\cos\\left(90^{\\circ}-\\angle ADB\\right)=\\sin\\angle ADB=\\frac{\\sqrt{2}}{5}\\)。\n在 \\(\\triangle BDC\\) 中，由余弦定理 \\(BC^{2}=BD^{2}+DC^{2}-2\\cdot BD\\cdot DC\\cdot\\cos\\angle BDC\\)。\n代入 \\(BD=5,\\ DC=2\\sqrt{2}\\) 得 \\(BC^{2}=25+8-2\\times 5\\times 2\\sqrt{2}\\times\\frac{\\sqrt{2}}{5}\\)。\n其中 \\(2\\times 5\\times 2\\sqrt{2}\\times\\frac{\\sqrt{2}}{5}=8\\)，所以 \\(BC^{2}=33-8=25\\)。\n故 \\(BC=5\\)。","scoring":[{"text":"在 \\(\\triangle ABD\\) 中用正弦定理求出 \\(\\sin\\angle ADB=\\frac{\\sqrt{2}}{5}\\)","points":3},{"text":"由 \\(AB<BD\\) 判断 \\(\\angle ADB\\) 为锐角，求得 \\(\\cos\\angle ADB=\\frac{\\sqrt{23}}{5}\\)","points":3},{"text":"由 \\(\\angle ADC=90^{\\circ}\\) 得 \\(\\cos\\angle BDC=\\sin\\angle ADB=\\frac{\\sqrt{2}}{5}\\)","points":3},{"text":"在 \\(\\triangle BDC\\) 中用余弦定理求 \\(BC^{2}=25\\)，得 \\(BC=5\\)","points":3}]},"triangle-big-009":{"final":"（I）\\(A=\\frac{\\pi}{3}\\)；（II）\\(AC\\) 边上的高为 \\(\\frac{3\\sqrt{3}}{2}\\)。","solution":"（I）因为 \\(B\\in(0,\\pi)\\) 且 \\(\\cos B=-\\frac{1}{7}<0\\)，所以 \\(B\\) 为钝角，\\(\\sin B=\\sqrt{1-\\left(-\\frac{1}{7}\\right)^{2}}=\\frac{4\\sqrt{3}}{7}\\)。\n由正弦定理 \\(\\frac{a}{\\sin A}=\\frac{b}{\\sin B}\\)，得 \\(\\sin A=\\frac{a\\sin B}{b}=\\frac{7\\times\\frac{4\\sqrt{3}}{7}}{8}=\\frac{\\sqrt{3}}{2}\\)。\n因为 \\(B\\) 为钝角，所以 \\(A\\) 为锐角，故 \\(A=\\frac{\\pi}{3}\\)。\n（II）因为 \\(C=\\pi-A-B\\)，所以 \\(\\sin C=\\sin(A+B)=\\sin A\\cos B+\\cos A\\sin B\\)。\n代入得 \\(\\sin C=\\frac{\\sqrt{3}}{2}\\times\\left(-\\frac{1}{7}\\right)+\\frac{1}{2}\\times\\frac{4\\sqrt{3}}{7}=-\\frac{\\sqrt{3}}{14}+\\frac{2\\sqrt{3}}{7}=\\frac{3\\sqrt{3}}{14}\\)。\n由正弦定理 \\(c=\\frac{a\\sin C}{\\sin A}=\\frac{7\\times\\frac{3\\sqrt{3}}{14}}{\\frac{\\sqrt{3}}{2}}=3\\)，即 \\(AB=3\\)。\n设 \\(AC\\) 边上的高为 \\(h\\)，则面积 \\(S=\\frac{1}{2}bh=\\frac{1}{2}ac\\sin B\\)。\n所以 \\(h=\\frac{ac\\sin B}{b}=\\frac{7\\times 3\\times\\frac{4\\sqrt{3}}{7}}{8}=\\frac{12\\sqrt{3}}{8}=\\frac{3\\sqrt{3}}{2}\\)。","scoring":[{"text":"由 \\(\\cos B=-\\frac{1}{7}\\) 求 \\(\\sin B=\\frac{4\\sqrt{3}}{7}\\)","points":2},{"text":"用正弦定理求 \\(\\sin A=\\frac{\\sqrt{3}}{2}\\)，结合 \\(B\\) 为钝角得 \\(A=\\frac{\\pi}{3}\\)","points":3},{"text":"用 \\(\\sin C=\\sin(A+B)\\) 求 \\(\\sin C=\\frac{3\\sqrt{3}}{14}\\)","points":2},{"text":"用正弦定理求 \\(c=AB=3\\)","points":2},{"text":"用面积关系 \\(S=\\frac{1}{2}bh\\) 求高 \\(h=\\frac{3\\sqrt{3}}{2}\\)","points":3}]},"triangle-big-010":{"final":"（I）\\(B=\\frac{\\pi}{3}\\)；（II）\\(b=\\sqrt{7}\\)，\\(\\sin(2A-B)=\\frac{3\\sqrt{3}}{14}\\)。","solution":"（I）由正弦定理 \\(\\frac{a}{\\sin A}=\\frac{b}{\\sin B}\\)，得 \\(b\\sin A=a\\sin B\\)。\n代入 \\(b\\sin A=a\\cos\\left(B-\\frac{\\pi}{6}\\right)\\) 得 \\(a\\sin B=a\\cos\\left(B-\\frac{\\pi}{6}\\right)\\)。\n因为 \\(a>0\\)，两边约去 \\(a\\) 得 \\(\\sin B=\\cos\\left(B-\\frac{\\pi}{6}\\right)\\)。\n用差角公式展开右边：\\(\\cos\\left(B-\\frac{\\pi}{6}\\right)=\\cos B\\cos\\frac{\\pi}{6}+\\sin B\\sin\\frac{\\pi}{6}=\\frac{\\sqrt{3}}{2}\\cos B+\\frac{1}{2}\\sin B\\)。\n所以 \\(\\sin B=\\frac{\\sqrt{3}}{2}\\cos B+\\frac{1}{2}\\sin B\\)，移项得 \\(\\frac{1}{2}\\sin B=\\frac{\\sqrt{3}}{2}\\cos B\\)。\n即 \\(\\tan B=\\sqrt{3}\\)，又 \\(B\\in(0,\\pi)\\)，故 \\(B=\\frac{\\pi}{3}\\)。\n（II）由余弦定理 \\(b^{2}=a^{2}+c^{2}-2ac\\cos B=4+9-2\\times 2\\times 3\\times\\frac{1}{2}=7\\)，所以 \\(b=\\sqrt{7}\\)。\n由余弦定理 \\(\\cos A=\\frac{b^{2}+c^{2}-a^{2}}{2bc}=\\frac{7+9-4}{2\\times\\sqrt{7}\\times 3}=\\frac{12}{6\\sqrt{7}}=\\frac{2\\sqrt{7}}{7}\\)。\n因为 \\(A\\in(0,\\pi)\\)，所以 \\(\\sin A=\\sqrt{1-\\frac{4}{7}}=\\frac{\\sqrt{3}}{\\sqrt{7}}=\\frac{\\sqrt{21}}{7}\\)。\n由二倍角公式 \\(\\sin 2A=2\\sin A\\cos A=2\\times\\frac{\\sqrt{3}}{\\sqrt{7}}\\times\\frac{2}{\\sqrt{7}}=\\frac{4\\sqrt{3}}{7}\\)，\\(\\cos 2A=2\\cos^{2}A-1=2\\times\\frac{4}{7}-1=\\frac{1}{7}\\)。\n所以 \\(\\sin(2A-B)=\\sin 2A\\cos B-\\cos 2A\\sin B=\\frac{4\\sqrt{3}}{7}\\times\\frac{1}{2}-\\frac{1}{7}\\times\\frac{\\sqrt{3}}{2}\\)。\n即 \\(\\sin(2A-B)=\\frac{2\\sqrt{3}}{7}-\\frac{\\sqrt{3}}{14}=\\frac{4\\sqrt{3}-\\sqrt{3}}{14}=\\frac{3\\sqrt{3}}{14}\\)。","scoring":[{"text":"用正弦定理把条件化为 \\(\\sin B=\\cos\\left(B-\\frac{\\pi}{6}\\right)\\)","points":3},{"text":"展开并化简得 \\(\\tan B=\\sqrt{3}\\)，从而 \\(B=\\frac{\\pi}{3}\\)","points":3},{"text":"用余弦定理求 \\(b=\\sqrt{7}\\)","points":2},{"text":"求 \\(\\cos A,\\ \\sin A\\)，并用二倍角公式求 \\(\\sin 2A,\\ \\cos 2A\\)","points":2},{"text":"用差角公式求得 \\(\\sin(2A-B)=\\frac{3\\sqrt{3}}{14}\\)","points":2}]},"triangle-big-011":{"final":"(1) \\(A=\\dfrac{\\pi}{3}\\)；(2) \\(\\sin C=\\dfrac{\\sqrt{6}+\\sqrt{2}}{4}\\)","solution":"(1) 把已知等式的左边展开，得 \\(\\sin^{2}B-2\\sin B\\sin C+\\sin^{2}C=\\sin^{2}A-\\sin B\\sin C\\)．\n移项整理，得 \\(\\sin^{2}B+\\sin^{2}C-\\sin^{2}A=\\sin B\\sin C\\)．\n由正弦定理 \\(\\sin A=\\dfrac{a}{2R}\\)，\\(\\sin B=\\dfrac{b}{2R}\\)，\\(\\sin C=\\dfrac{c}{2R}\\)，代入上式并约去 \\(\\dfrac{1}{4R^{2}}\\)，得 \\(b^{2}+c^{2}-a^{2}=bc\\)．\n由余弦定理得 \\(\\cos A=\\dfrac{b^{2}+c^{2}-a^{2}}{2bc}=\\dfrac{bc}{2bc}=\\dfrac{1}{2}\\)．\n因为 \\(0<A<\\pi\\)，所以 \\(A=\\dfrac{\\pi}{3}\\)．\n\n(2) 由 \\(A=\\dfrac{\\pi}{3}\\) 得 \\(B+C=\\dfrac{2\\pi}{3}\\)，即 \\(B=\\dfrac{2\\pi}{3}-C\\)，且 \\(0<C<\\dfrac{2\\pi}{3}\\)．\n对 \\(\\sqrt{2}\\,a+b=2c\\) 用正弦定理，得 \\(\\sqrt{2}\\sin A+\\sin B=2\\sin C\\)．\n把 \\(\\sin A=\\dfrac{\\sqrt{3}}{2}\\) 与 \\(\\sin B=\\sin\\left(\\dfrac{2\\pi}{3}-C\\right)=\\dfrac{\\sqrt{3}}{2}\\cos C+\\dfrac{1}{2}\\sin C\\) 代入，得 \\(\\dfrac{\\sqrt{6}}{2}+\\dfrac{\\sqrt{3}}{2}\\cos C+\\dfrac{1}{2}\\sin C=2\\sin C\\)．\n两边乘 \\(2\\) 并整理，得 \\(3\\sin C-\\sqrt{3}\\cos C=\\sqrt{6}\\)．\n两边同除以 \\(2\\sqrt{3}\\)，得 \\(\\dfrac{\\sqrt{3}}{2}\\sin C-\\dfrac{1}{2}\\cos C=\\dfrac{\\sqrt{2}}{2}\\)，即 \\(\\sin\\left(C-\\dfrac{\\pi}{6}\\right)=\\dfrac{\\sqrt{2}}{2}\\)．\n由 \\(0<C<\\dfrac{2\\pi}{3}\\) 得 \\(-\\dfrac{\\pi}{6}<C-\\dfrac{\\pi}{6}<\\dfrac{\\pi}{2}\\)，这个范围内正弦值为 \\(\\dfrac{\\sqrt{2}}{2}\\) 的角只有 \\(\\dfrac{\\pi}{4}\\)，故 \\(C-\\dfrac{\\pi}{6}=\\dfrac{\\pi}{4}\\)．\n所以 \\(C=\\dfrac{5\\pi}{12}\\)，从而 \\(\\sin C=\\sin 75^{\\circ}=\\sin\\left(45^{\\circ}+30^{\\circ}\\right)=\\dfrac{\\sqrt{2}}{2}\\cdot\\dfrac{\\sqrt{3}}{2}+\\dfrac{\\sqrt{2}}{2}\\cdot\\dfrac{1}{2}=\\dfrac{\\sqrt{6}+\\sqrt{2}}{4}\\)．","scoring":[{"text":"展开已知等式并移项，得到 \\(\\sin^{2}B+\\sin^{2}C-\\sin^{2}A=\\sin B\\sin C\\)","points":2},{"text":"用正弦定理把正弦关系化成边的关系，得 \\(b^{2}+c^{2}-a^{2}=bc\\)","points":3},{"text":"由余弦定理求出 \\(\\cos A=\\dfrac{1}{2}\\)，得 \\(A=\\dfrac{\\pi}{3}\\)","points":3},{"text":"对 \\(\\sqrt{2}a+b=2c\\) 用正弦定理并整理，得 \\(3\\sin C-\\sqrt{3}\\cos C=\\sqrt{6}\\)","points":2},{"text":"化为 \\(\\sin\\left(C-\\dfrac{\\pi}{6}\\right)=\\dfrac{\\sqrt{2}}{2}\\)，结合角的范围得 \\(C=\\dfrac{5\\pi}{12}\\)，进而 \\(\\sin C=\\dfrac{\\sqrt{6}+\\sqrt{2}}{4}\\)","points":2}]},"triangle-big-012":{"final":"(1) \\(B=\\dfrac{\\pi}{3}\\)；(2) \\(\\triangle ABC\\) 面积的取值范围是 \\(\\left(\\dfrac{\\sqrt{3}}{8},\\dfrac{\\sqrt{3}}{2}\\right)\\)","solution":"(1) 因为 \\(A+B+C=\\pi\\)，所以 \\(\\dfrac{A+C}{2}=\\dfrac{\\pi}{2}-\\dfrac{B}{2}\\)，从而 \\(\\sin\\dfrac{A+C}{2}=\\cos\\dfrac{B}{2}\\)．\n于是已知条件化为 \\(a\\cos\\dfrac{B}{2}=b\\sin A\\)．\n由正弦定理 \\(\\dfrac{a}{\\sin A}=\\dfrac{b}{\\sin B}\\) 得 \\(a\\sin B=b\\sin A\\)，代入上式得 \\(a\\cos\\dfrac{B}{2}=a\\sin B\\)．\n因为 \\(a>0\\)，所以 \\(\\cos\\dfrac{B}{2}=\\sin B=2\\sin\\dfrac{B}{2}\\cos\\dfrac{B}{2}\\)．\n因为 \\(0<\\dfrac{B}{2}<\\dfrac{\\pi}{2}\\)，所以 \\(\\cos\\dfrac{B}{2}\\neq0\\)，两边约去得 \\(\\sin\\dfrac{B}{2}=\\dfrac{1}{2}\\)．\n于是 \\(\\dfrac{B}{2}=\\dfrac{\\pi}{6}\\)，即 \\(B=\\dfrac{\\pi}{3}\\)．\n\n(2) 由 \\(B=\\dfrac{\\pi}{3}\\) 得 \\(A+C=\\dfrac{2\\pi}{3}\\)．\n因为 \\(\\triangle ABC\\) 为锐角三角形，所以 \\(0<A<\\dfrac{\\pi}{2}\\) 且 \\(0<C=\\dfrac{2\\pi}{3}-A<\\dfrac{\\pi}{2}\\)，解得 \\(\\dfrac{\\pi}{6}<A<\\dfrac{\\pi}{2}\\)．\n由正弦定理 \\(\\dfrac{a}{\\sin A}=\\dfrac{c}{\\sin C}\\) 及 \\(c=1\\) 得 \\(a=\\dfrac{\\sin A}{\\sin C}=\\dfrac{\\sin A}{\\sin\\left(\\dfrac{2\\pi}{3}-A\\right)}\\)．\n又 \\(\\sin\\left(\\dfrac{2\\pi}{3}-A\\right)=\\dfrac{\\sqrt{3}}{2}\\cos A+\\dfrac{1}{2}\\sin A\\)，所以面积 \\(S=\\dfrac{1}{2}ac\\sin B=\\dfrac{\\sqrt{3}}{4}\\cdot\\dfrac{\\sin A}{\\dfrac{\\sqrt{3}}{2}\\cos A+\\dfrac{1}{2}\\sin A}=\\dfrac{\\sqrt{3}}{2}\\cdot\\dfrac{\\sin A}{\\sqrt{3}\\cos A+\\sin A}\\)．\n因为 \\(\\cos A>0\\)，把分子分母同除以 \\(\\cos A\\)，得 \\(S=\\dfrac{\\sqrt{3}}{2}\\cdot\\dfrac{\\tan A}{\\sqrt{3}+\\tan A}\\)，其中 \\(t=\\tan A\\in\\left(\\dfrac{\\sqrt{3}}{3},+\\infty\\right)\\)．\n记 \\(g(t)=\\dfrac{t}{\\sqrt{3}+t}=1-\\dfrac{\\sqrt{3}}{\\sqrt{3}+t}\\)，则 \\(g(t)\\) 在 \\(\\left(\\dfrac{\\sqrt{3}}{3},+\\infty\\right)\\) 上单调递增．\n又 \\(g\\left(\\dfrac{\\sqrt{3}}{3}\\right)=\\dfrac{1}{4}\\)，且对任意 \\(t>\\dfrac{\\sqrt{3}}{3}\\) 都有 \\(0<\\dfrac{\\sqrt{3}}{\\sqrt{3}+t}<\\dfrac{3}{4}\\)，故 \\(g(t)\\) 的值域为 \\(\\left(\\dfrac{1}{4},1\\right)\\)．\n所以 \\(S\\in\\left(\\dfrac{\\sqrt{3}}{2}\\times\\dfrac{1}{4},\\dfrac{\\sqrt{3}}{2}\\times 1\\right)=\\left(\\dfrac{\\sqrt{3}}{8},\\dfrac{\\sqrt{3}}{2}\\right)\\)．","scoring":[{"text":"由 \\(A+B+C=\\pi\\) 把 \\(\\sin\\dfrac{A+C}{2}\\) 化为 \\(\\cos\\dfrac{B}{2}\\)，已知式变为 \\(a\\cos\\dfrac{B}{2}=b\\sin A\\)","points":2},{"text":"用正弦定理 \\(a\\sin B=b\\sin A\\) 代入并约去 \\(a\\)，得 \\(\\cos\\dfrac{B}{2}=\\sin B\\)，再由二倍角与 \\(\\cos\\dfrac{B}{2}\\neq0\\) 得 \\(\\sin\\dfrac{B}{2}=\\dfrac{1}{2}\\)","points":3},{"text":"求出 \\(B=\\dfrac{\\pi}{3}\\)","points":2},{"text":"由锐角三角形条件求出 \\(\\dfrac{\\pi}{6}<A<\\dfrac{\\pi}{2}\\)","points":2},{"text":"用正弦定理表示 \\(a\\)，把面积化为 \\(S=\\dfrac{\\sqrt{3}}{2}\\cdot\\dfrac{\\tan A}{\\sqrt{3}+\\tan A}\\)，再由单调性求出取值范围 \\(\\left(\\dfrac{\\sqrt{3}}{8},\\dfrac{\\sqrt{3}}{2}\\right)\\)","points":3}]},"triangle-big-013":{"final":"(1) \\(B=\\dfrac{\\pi}{3}\\)；(2) \\(\\triangle ABC\\) 面积的取值范围是 \\(\\left(\\dfrac{\\sqrt{3}}{8},\\dfrac{\\sqrt{3}}{2}\\right)\\)","solution":"(1) 由 \\(A+B+C=\\pi\\) 可得 \\(\\dfrac{A+C}{2}=\\dfrac{\\pi}{2}-\\dfrac{B}{2}\\)，故 \\(\\sin\\dfrac{A+C}{2}=\\cos\\dfrac{B}{2}\\)，原条件即 \\(a\\cos\\dfrac{B}{2}=b\\sin A\\)．\n由正弦定理有 \\(a\\sin B=b\\sin A\\)，所以上式即 \\(a\\cos\\dfrac{B}{2}=a\\sin B\\)．\n因为 \\(a>0\\)，约去 \\(a\\) 得 \\(\\cos\\dfrac{B}{2}=\\sin B=2\\sin\\dfrac{B}{2}\\cos\\dfrac{B}{2}\\)．\n因为 \\(0<\\dfrac{B}{2}<\\dfrac{\\pi}{2}\\)，故 \\(\\cos\\dfrac{B}{2}>0\\)，两边约去 \\(\\cos\\dfrac{B}{2}\\) 得 \\(\\sin\\dfrac{B}{2}=\\dfrac{1}{2}\\)．\n所以 \\(\\dfrac{B}{2}=\\dfrac{\\pi}{6}\\)，即 \\(B=\\dfrac{\\pi}{3}\\)．\n\n(2) 由 \\(B=\\dfrac{\\pi}{3}\\) 知 \\(A+C=\\dfrac{2\\pi}{3}\\)，即 \\(C=\\dfrac{2\\pi}{3}-A\\)．\n因为三角形为锐角三角形，需 \\(0<A<\\dfrac{\\pi}{2}\\) 且 \\(0<\\dfrac{2\\pi}{3}-A<\\dfrac{\\pi}{2}\\)，所以 \\(\\dfrac{\\pi}{6}<A<\\dfrac{\\pi}{2}\\)．\n由正弦定理 \\(\\dfrac{a}{\\sin A}=\\dfrac{c}{\\sin C}\\) 与 \\(c=1\\)，得 \\(a=\\dfrac{\\sin A}{\\sin\\left(\\dfrac{2\\pi}{3}-A\\right)}\\)．\n展开 \\(\\sin\\left(\\dfrac{2\\pi}{3}-A\\right)=\\dfrac{\\sqrt{3}}{2}\\cos A+\\dfrac{1}{2}\\sin A\\)，则面积 \\(S=\\dfrac{1}{2}ac\\sin B=\\dfrac{\\sqrt{3}}{4}\\cdot\\dfrac{\\sin A}{\\dfrac{\\sqrt{3}}{2}\\cos A+\\dfrac{1}{2}\\sin A}=\\dfrac{\\sqrt{3}}{2}\\cdot\\dfrac{\\sin A}{\\sqrt{3}\\cos A+\\sin A}\\)．\n因为 \\(\\cos A>0\\)，分子分母同除以 \\(\\cos A\\)，得 \\(S=\\dfrac{\\sqrt{3}}{2}\\cdot\\dfrac{\\tan A}{\\sqrt{3}+\\tan A}\\)．\n令 \\(t=\\tan A\\)，由 \\(\\dfrac{\\pi}{6}<A<\\dfrac{\\pi}{2}\\) 得 \\(t\\in\\left(\\dfrac{\\sqrt{3}}{3},+\\infty\\right)\\)，而 \\(\\dfrac{t}{\\sqrt{3}+t}=1-\\dfrac{\\sqrt{3}}{\\sqrt{3}+t}\\) 关于 \\(t\\) 单调递增．\n当 \\(t=\\dfrac{\\sqrt{3}}{3}\\) 时 \\(\\dfrac{t}{\\sqrt{3}+t}=\\dfrac{1}{4}\\)；当 \\(t>\\dfrac{\\sqrt{3}}{3}\\) 时 \\(0<\\dfrac{\\sqrt{3}}{\\sqrt{3}+t}<\\dfrac{3}{4}\\)，所以 \\(\\dfrac{t}{\\sqrt{3}+t}\\in\\left(\\dfrac{1}{4},1\\right)\\)．\n故 \\(S\\in\\left(\\dfrac{\\sqrt{3}}{8},\\dfrac{\\sqrt{3}}{2}\\right)\\)，即面积的取值范围为 \\(\\left(\\dfrac{\\sqrt{3}}{8},\\dfrac{\\sqrt{3}}{2}\\right)\\)．","scoring":[{"text":"由 \\(\\sin\\dfrac{A+C}{2}=\\cos\\dfrac{B}{2}\\) 把已知式化为 \\(a\\cos\\dfrac{B}{2}=b\\sin A\\)","points":2},{"text":"用正弦定理 \\(a\\sin B=b\\sin A\\) 化得 \\(\\cos\\dfrac{B}{2}=\\sin B\\)，约去 \\(\\cos\\dfrac{B}{2}\\) 得 \\(\\sin\\dfrac{B}{2}=\\dfrac{1}{2}\\)","points":3},{"text":"求出 \\(B=\\dfrac{\\pi}{3}\\)","points":2},{"text":"由锐角三角形条件得 \\(\\dfrac{\\pi}{6}<A<\\dfrac{\\pi}{2}\\)","points":2},{"text":"用正弦定理表示 \\(a\\)，把面积写成 \\(S=\\dfrac{\\sqrt{3}}{2}\\cdot\\dfrac{\\tan A}{\\sqrt{3}+\\tan A}\\)，由关于 \\(\\tan A\\) 的单调性求出面积范围 \\(\\left(\\dfrac{\\sqrt{3}}{8},\\dfrac{\\sqrt{3}}{2}\\right)\\)","points":3}]},"triangle-big-014":{"final":"(Ⅰ) \\(b=7\\)，\\(c=5\\)；(Ⅱ) \\(\\sin(B-C)=\\dfrac{4\\sqrt{3}}{7}\\)","solution":"(Ⅰ) 由余弦定理 \\(b^{2}=a^{2}+c^{2}-2ac\\cos B\\)，代入 \\(a=3\\)，\\(\\cos B=-\\dfrac{1}{2}\\)，得 \\(b^{2}=9+c^{2}+3c\\)．\n又 \\(b=c+2\\)，代入上式得 \\((c+2)^{2}=9+c^{2}+3c\\)，即 \\(c^{2}+4c+4=c^{2}+3c+9\\)．\n解得 \\(c=5\\)，于是 \\(b=c+2=7\\)．\n\n(Ⅱ) 由 \\(\\cos B=-\\dfrac{1}{2}\\) 且 \\(0<B<\\pi\\)，得 \\(B=\\dfrac{2\\pi}{3}\\)，\\(\\sin B=\\dfrac{\\sqrt{3}}{2}\\)．\n由正弦定理 \\(\\dfrac{b}{\\sin B}=\\dfrac{c}{\\sin C}\\) 得 \\(\\sin C=\\dfrac{c\\sin B}{b}=\\dfrac{5\\times\\dfrac{\\sqrt{3}}{2}}{7}=\\dfrac{5\\sqrt{3}}{14}\\)．\n由余弦定理 \\(\\cos C=\\dfrac{a^{2}+b^{2}-c^{2}}{2ab}=\\dfrac{9+49-25}{2\\times3\\times7}=\\dfrac{33}{42}=\\dfrac{11}{14}\\)（\\(C\\) 为三角形内角，取正值）．\n所以 \\(\\sin(B-C)=\\sin B\\cos C-\\cos B\\sin C=\\dfrac{\\sqrt{3}}{2}\\times\\dfrac{11}{14}-\\left(-\\dfrac{1}{2}\\right)\\times\\dfrac{5\\sqrt{3}}{14}\\)．\n计算得 \\(\\sin(B-C)=\\dfrac{11\\sqrt{3}}{28}+\\dfrac{5\\sqrt{3}}{28}=\\dfrac{16\\sqrt{3}}{28}=\\dfrac{4\\sqrt{3}}{7}\\)．","scoring":[{"text":"由余弦定理建立 \\(b,c\\) 的关系 \\(b^{2}=9+c^{2}+3c\\)","points":3},{"text":"代入 \\(b=c+2\\) 解方程，得 \\(c=5\\)，\\(b=7\\)","points":3},{"text":"由 \\(\\cos B=-\\dfrac{1}{2}\\) 得 \\(\\sin B=\\dfrac{\\sqrt{3}}{2}\\)，并用正弦定理求 \\(\\sin C=\\dfrac{5\\sqrt{3}}{14}\\)","points":2},{"text":"用余弦定理求出 \\(\\cos C=\\dfrac{11}{14}\\)","points":2},{"text":"用两角差的正弦公式求出 \\(\\sin(B-C)=\\dfrac{4\\sqrt{3}}{7}\\)","points":2}]},"triangle-big-015":{"final":"(Ⅰ) \\(b=7\\)，\\(c=5\\)；(Ⅱ) \\(\\sin(B+C)=\\dfrac{3\\sqrt{3}}{14}\\)","solution":"(Ⅰ) 由余弦定理 \\(b^{2}=a^{2}+c^{2}-2ac\\cos B\\)，把 \\(a=3\\)，\\(\\cos B=-\\dfrac{1}{2}\\) 代入，得 \\(b^{2}=9+c^{2}+3c\\)．\n再由 \\(b=c+2\\) 得 \\((c+2)^{2}=9+c^{2}+3c\\)，化简为 \\(c^{2}+4c+4=c^{2}+3c+9\\)．\n解之得 \\(c=5\\)，从而 \\(b=7\\)．\n\n(Ⅱ) 由 \\(\\cos B=-\\dfrac{1}{2}\\) 且 \\(B\\in(0,\\pi)\\) 知 \\(B=\\dfrac{2\\pi}{3}\\)，故 \\(\\sin B=\\dfrac{\\sqrt{3}}{2}\\)．\n因为 \\(A+B+C=\\pi\\)，所以 \\(\\sin(B+C)=\\sin A\\)．\n由正弦定理 \\(\\dfrac{a}{\\sin A}=\\dfrac{b}{\\sin B}\\) 得 \\(\\sin A=\\dfrac{a\\sin B}{b}=\\dfrac{3\\times\\dfrac{\\sqrt{3}}{2}}{7}=\\dfrac{3\\sqrt{3}}{14}\\)．\n所以 \\(\\sin(B+C)=\\sin A=\\dfrac{3\\sqrt{3}}{14}\\)．","scoring":[{"text":"由余弦定理得 \\(b^{2}=9+c^{2}+3c\\)","points":3},{"text":"结合 \\(b=c+2\\) 解出 \\(c=5\\)，\\(b=7\\)","points":3},{"text":"由 \\(\\cos B=-\\dfrac{1}{2}\\) 求出 \\(\\sin B=\\dfrac{\\sqrt{3}}{2}\\)","points":2},{"text":"利用 \\(\\sin(B+C)=\\sin A\\) 及正弦定理求出 \\(\\sin A=\\dfrac{3\\sqrt{3}}{14}\\)，得 \\(\\sin(B+C)=\\dfrac{3\\sqrt{3}}{14}\\)","points":4}]},"triangle-big-016":{"final":"(Ⅰ) \\(\\cos B=-\\dfrac{1}{4}\\)；(Ⅱ) \\(\\sin\\left(2B+\\dfrac{\\pi}{6}\\right)=-\\dfrac{3\\sqrt{5}+7}{16}\\)","solution":"(Ⅰ) 由正弦定理 \\(\\dfrac{b}{\\sin B}=\\dfrac{c}{\\sin C}\\) 得 \\(c\\sin B=b\\sin C\\)．\n代入 \\(3c\\sin B=4a\\sin C\\)，得 \\(3b\\sin C=4a\\sin C\\)．\n因为 \\(\\sin C>0\\)，所以 \\(3b=4a\\)，即 \\(b=\\dfrac{4a}{3}\\)．\n由 \\(b+c=2a\\) 得 \\(c=2a-\\dfrac{4a}{3}=\\dfrac{2a}{3}\\)．\n由余弦定理，\\(\\cos B=\\dfrac{a^{2}+c^{2}-b^{2}}{2ac}=\\dfrac{a^{2}+\\dfrac{4a^{2}}{9}-\\dfrac{16a^{2}}{9}}{2\\cdot a\\cdot\\dfrac{2a}{3}}=\\dfrac{-\\dfrac{3a^{2}}{9}}{\\dfrac{4a^{2}}{3}}=-\\dfrac{1}{4}\\)．\n\n(Ⅱ) 因为 \\(0<B<\\pi\\) 且 \\(\\cos B=-\\dfrac{1}{4}<0\\)，所以 \\(B\\) 为钝角，\\(\\sin B=\\sqrt{1-\\cos^{2}B}=\\sqrt{1-\\dfrac{1}{16}}=\\dfrac{\\sqrt{15}}{4}\\)．\n于是 \\(\\sin 2B=2\\sin B\\cos B=2\\times\\dfrac{\\sqrt{15}}{4}\\times\\left(-\\dfrac{1}{4}\\right)=-\\dfrac{\\sqrt{15}}{8}\\)．\n又 \\(\\cos 2B=2\\cos^{2}B-1=2\\times\\dfrac{1}{16}-1=-\\dfrac{7}{8}\\)．\n所以 \\(\\sin\\left(2B+\\dfrac{\\pi}{6}\\right)=\\sin 2B\\cos\\dfrac{\\pi}{6}+\\cos 2B\\sin\\dfrac{\\pi}{6}=-\\dfrac{\\sqrt{15}}{8}\\times\\dfrac{\\sqrt{3}}{2}-\\dfrac{7}{8}\\times\\dfrac{1}{2}\\)．\n计算得 \\(\\sin\\left(2B+\\dfrac{\\pi}{6}\\right)=-\\dfrac{\\sqrt{45}}{16}-\\dfrac{7}{16}=-\\dfrac{3\\sqrt{5}+7}{16}\\)．","scoring":[{"text":"用正弦定理把 \\(3c\\sin B=4a\\sin C\\) 化成 \\(3b=4a\\)","points":3},{"text":"结合 \\(b+c=2a\\) 得 \\(b=\\dfrac{4a}{3}\\)，\\(c=\\dfrac{2a}{3}\\)","points":2},{"text":"由余弦定理求出 \\(\\cos B=-\\dfrac{1}{4}\\)","points":3},{"text":"求出 \\(\\sin B=\\dfrac{\\sqrt{15}}{4}\\)，进而 \\(\\sin 2B=-\\dfrac{\\sqrt{15}}{8}\\)，\\(\\cos 2B=-\\dfrac{7}{8}\\)","points":2},{"text":"用两角和的正弦公式求出 \\(\\sin\\left(2B+\\dfrac{\\pi}{6}\\right)=-\\dfrac{3\\sqrt{5}+7}{16}\\)","points":2}]},"triangle-big-017":{"final":"(Ⅰ) \\(\\cos B=-\\dfrac{1}{4}\\)；(Ⅱ) \\(\\sin\\left(2B+\\dfrac{\\pi}{6}\\right)=-\\dfrac{3\\sqrt{5}+7}{16}\\)","solution":"(Ⅰ) 由正弦定理 \\(\\dfrac{b}{\\sin B}=\\dfrac{c}{\\sin C}\\) 可得 \\(c\\sin B=b\\sin C\\)．\n把它代入已知的 \\(3c\\sin B=4a\\sin C\\)，得 \\(3b\\sin C=4a\\sin C\\)．\n因为 \\(\\sin C>0\\)，约去 \\(\\sin C\\) 得 \\(3b=4a\\)，即 \\(b=\\dfrac{4a}{3}\\)．\n由 \\(b+c=2a\\) 得 \\(c=2a-\\dfrac{4a}{3}=\\dfrac{2a}{3}\\)．\n代入余弦定理 \\(\\cos B=\\dfrac{a^{2}+c^{2}-b^{2}}{2ac}=\\dfrac{a^{2}+\\dfrac{4}{9}a^{2}-\\dfrac{16}{9}a^{2}}{2\\cdot a\\cdot\\dfrac{2}{3}a}=\\dfrac{-\\dfrac{1}{3}a^{2}}{\\dfrac{4}{3}a^{2}}=-\\dfrac{1}{4}\\)．\n\n(Ⅱ) 因为 \\(0<B<\\pi\\)，\\(\\cos B=-\\dfrac{1}{4}<0\\)，所以 \\(B\\) 为钝角，\\(\\sin B=\\sqrt{1-\\cos^{2}B}=\\dfrac{\\sqrt{15}}{4}\\)．\n由二倍角公式 \\(\\sin 2B=2\\sin B\\cos B=-\\dfrac{\\sqrt{15}}{8}\\)，\\(\\cos 2B=2\\cos^{2}B-1=-\\dfrac{7}{8}\\)．\n所以 \\(\\sin\\left(2B+\\dfrac{\\pi}{6}\\right)=\\sin 2B\\cos\\dfrac{\\pi}{6}+\\cos 2B\\sin\\dfrac{\\pi}{6}=\\left(-\\dfrac{\\sqrt{15}}{8}\\right)\\times\\dfrac{\\sqrt{3}}{2}+\\left(-\\dfrac{7}{8}\\right)\\times\\dfrac{1}{2}\\)．\n即 \\(\\sin\\left(2B+\\dfrac{\\pi}{6}\\right)=-\\dfrac{3\\sqrt{5}}{16}-\\dfrac{7}{16}=-\\dfrac{3\\sqrt{5}+7}{16}\\)．","scoring":[{"text":"用正弦定理把条件化成 \\(3b=4a\\)","points":3},{"text":"结合 \\(b+c=2a\\) 得 \\(b=\\dfrac{4a}{3}\\)，\\(c=\\dfrac{2a}{3}\\)","points":2},{"text":"由余弦定理求出 \\(\\cos B=-\\dfrac{1}{4}\\)","points":3},{"text":"求出 \\(\\sin B=\\dfrac{\\sqrt{15}}{4}\\)，并算出 \\(\\sin 2B=-\\dfrac{\\sqrt{15}}{8}\\)，\\(\\cos 2B=-\\dfrac{7}{8}\\)","points":2},{"text":"用两角和的正弦公式求出 \\(\\sin\\left(2B+\\dfrac{\\pi}{6}\\right)=-\\dfrac{3\\sqrt{5}+7}{16}\\)","points":2}]},"triangle-big-018":{"final":"(1) \\(c=\\dfrac{\\sqrt{3}}{3}\\)；(2) \\(\\sin\\left(B+\\dfrac{\\pi}{3}\\right)=\\dfrac{2\\sqrt{15}+\\sqrt{5}}{10}\\)","solution":"(1) 由余弦定理 \\(b^{2}=a^{2}+c^{2}-2ac\\cos B\\)，把 \\(a=3c\\)，\\(b=\\sqrt{2}\\)，\\(\\cos B=\\dfrac{2}{3}\\) 代入，得 \\(2=9c^{2}+c^{2}-2\\times 3c\\times c\\times\\dfrac{2}{3}\\)．\n即 \\(2=10c^{2}-4c^{2}=6c^{2}\\)，所以 \\(c^{2}=\\dfrac{1}{3}\\)．\n因为 \\(c>0\\)，所以 \\(c=\\dfrac{\\sqrt{3}}{3}\\)．\n\n(2) 由正弦定理 \\(\\dfrac{a}{\\sin A}=\\dfrac{b}{\\sin B}\\) 得 \\(\\dfrac{\\sin A}{a}=\\dfrac{\\sin B}{b}\\)．\n代入条件 \\(\\dfrac{\\sin A}{a}=\\dfrac{\\cos B}{2b}\\)，得 \\(\\dfrac{\\sin B}{b}=\\dfrac{\\cos B}{2b}\\)．\n因为 \\(b>0\\)，所以 \\(\\cos B=2\\sin B\\)，即 \\(\\tan B=\\dfrac{1}{2}\\)；又 \\(\\cos B>0\\)，故 \\(B\\) 为锐角．\n由 \\(\\sin^{2}B+\\cos^{2}B=1\\) 解得 \\(\\sin B=\\dfrac{1}{\\sqrt{5}}=\\dfrac{\\sqrt{5}}{5}\\)，\\(\\cos B=\\dfrac{2}{\\sqrt{5}}=\\dfrac{2\\sqrt{5}}{5}\\)．\n所以 \\(\\sin\\left(B+\\dfrac{\\pi}{3}\\right)=\\sin B\\cos\\dfrac{\\pi}{3}+\\cos B\\sin\\dfrac{\\pi}{3}=\\dfrac{\\sqrt{5}}{5}\\times\\dfrac{1}{2}+\\dfrac{2\\sqrt{5}}{5}\\times\\dfrac{\\sqrt{3}}{2}\\)．\n计算得 \\(\\sin\\left(B+\\dfrac{\\pi}{3}\\right)=\\dfrac{\\sqrt{5}}{10}+\\dfrac{\\sqrt{15}}{5}=\\dfrac{\\sqrt{5}+2\\sqrt{15}}{10}\\)．","scoring":[{"text":"由余弦定理代入 \\(a=3c\\) 得 \\(6c^{2}=2\\)","points":3},{"text":"解出 \\(c=\\dfrac{\\sqrt{3}}{3}\\)","points":2},{"text":"用正弦定理把条件化为 \\(\\dfrac{\\sin B}{b}=\\dfrac{\\cos B}{2b}\\)，得 \\(\\tan B=\\dfrac{1}{2}\\)","points":3},{"text":"求出 \\(\\sin B=\\dfrac{\\sqrt{5}}{5}\\)，\\(\\cos B=\\dfrac{2\\sqrt{5}}{5}\\)","points":2},{"text":"用两角和的正弦公式求出 \\(\\sin\\left(B+\\dfrac{\\pi}{3}\\right)=\\dfrac{2\\sqrt{15}+\\sqrt{5}}{10}\\)","points":2}]},"triangle-big-019":{"final":"(1) 弧 \\(BC\\) 的长约为 \\(16.3\\ \\mathrm{km}\\)；(2) 海岛 \\(D\\) 到海岸线的最短距离约为 \\(35.8\\ \\mathrm{km}\\)","solution":"(1) 由方位角知 \\(\\angle BDC=22^{\\circ}\\)，又 \\(\\angle CBD=68^{\\circ}\\)，所以在 \\(\\triangle BCD\\) 中 \\(\\angle BCD=180^{\\circ}-68^{\\circ}-22^{\\circ}=90^{\\circ}\\)．\n在直角三角形 \\(BCD\\) 中，\\(BC=BD\\sin\\angle BDC=39.2\\sin 22^{\\circ}\\approx 39.2\\times0.3746\\approx 14.68\\)．\n设弧 \\(BC\\) 所在圆的圆心为 \\(O\\)，半径为 \\(r\\)．因为弧 \\(BC\\) 是四分之一圆弧，所以 \\(\\angle BOC=90^{\\circ}\\)，从而 \\(BC=\\sqrt{2}\\,r\\)，即 \\(r=\\dfrac{BC}{\\sqrt{2}}\\approx\\dfrac{14.68}{1.414}\\approx 10.38\\)．\n所以弧 \\(BC\\) 的长 \\(l=\\dfrac{\\pi}{2}r\\approx\\dfrac{3.142}{2}\\times10.38\\approx16.3\\)，即弧 \\(BC\\) 的长约为 \\(16.3\\ \\mathrm{km}\\)．\n\n(2) 在 \\(\\triangle ABD\\) 中，\\(BD=39.2\\)，\\(AB=40\\)，\\(\\angle ADB=58^{\\circ}\\)．\n由余弦定理 \\(AB^{2}=AD^{2}+BD^{2}-2\\cdot AD\\cdot BD\\cos 58^{\\circ}\\)，即 \\(1600=AD^{2}+1536.64-41.55AD\\)．\n整理得 \\(AD^{2}-41.55AD-63.36=0\\)，解得 \\(AD\\approx\\dfrac{41.55+\\sqrt{1726.4+253.4}}{2}\\approx 43.02\\)（负根舍去）．\n设 \\(D\\) 到直线 \\(AB\\) 的距离为 \\(h\\)，用两种方式表示 \\(\\triangle ABD\\) 的面积：\\(\\dfrac{1}{2}AB\\cdot h=\\dfrac{1}{2}AD\\cdot BD\\sin\\angle ADB\\)．\n所以 \\(h=\\dfrac{AD\\cdot BD\\sin 58^{\\circ}}{AB}\\approx\\dfrac{43.02\\times39.2\\times0.8480}{40}\\approx 35.75\\)．\n由 \\(\\sin\\angle DAB=\\dfrac{BD\\sin 58^{\\circ}}{AB}\\approx\\dfrac{39.2\\times0.8480}{40}\\approx0.831\\) 得 \\(\\angle DAB\\approx56.2^{\\circ}\\)，又 \\(\\angle ABD\\approx180^{\\circ}-58^{\\circ}-56.2^{\\circ}=65.8^{\\circ}\\)，两个底角都是锐角，所以垂足落在线段 \\(AB\\) 上，即 \\(D\\) 到线段 \\(AB\\) 的距离为 \\(35.75\\ \\mathrm{km}\\)．\n因为 \\(\\angle BCD=90^{\\circ}\\)，即 \\(DC\\perp BC\\)，所以 \\(D\\) 到线段 \\(BC\\) 的距离为 \\(DC=BD\\cos 22^{\\circ}\\approx39.2\\times0.9272\\approx 36.35\\)．\n弧 \\(BC\\) 位于直线 \\(BC\\) 的与海岛 \\(D\\) 相异的一侧（弧向远离海岛的方向凸出），而 \\(DC\\perp BC\\)，故对弧上任一点 \\(P\\)，\\(\\angle DCP>90^{\\circ}\\)，在 \\(\\triangle DCP\\) 中 \\(DP>DC\\approx36.35\\)．\n比较可知 \\(35.75<36.35\\)，所以海岛 \\(D\\) 到海岸线的最短距离约为 \\(35.8\\ \\mathrm{km}\\)．","scoring":[{"text":"由方位角算出 \\(\\angle BDC=22^{\\circ}\\)，得 \\(\\angle BCD=90^{\\circ}\\)","points":2},{"text":"在直角 \\(\\triangle BCD\\) 中求出 \\(BC=39.2\\sin22^{\\circ}\\approx14.68\\)","points":2},{"text":"由四分之一圆弧得 \\(BC=\\sqrt{2}r\\)，求出半径 \\(r\\approx10.38\\)，得弧长 \\(l=\\dfrac{\\pi}{2}r\\approx16.3\\)","points":2},{"text":"在 \\(\\triangle ABD\\) 中用余弦定理求出 \\(AD\\approx43.02\\)","points":2},{"text":"用面积两种算法（或正弦定理）求出 \\(D\\) 到 \\(AB\\) 的距离 \\(h\\approx35.75\\)，并说明垂足在线段 \\(AB\\) 上","points":2},{"text":"比较 \\(D\\) 到线段 \\(BC\\) 的距离 \\(DC\\approx36.35\\) 及弧 \\(BC\\) 上各点距离更大，得出最短距离约 \\(35.8\\ \\mathrm{km}\\)","points":2}]},"triangle-big-020":{"final":"(1) \\(\\triangle ABC\\) 的面积为 \\(\\sqrt{3}\\)；(2) \\(C=15^{\\circ}\\)（即 \\(\\dfrac{\\pi}{12}\\)）","solution":"(1) 由余弦定理 \\(b^{2}=a^{2}+c^{2}-2ac\\cos B\\)，把 \\(B=150^{\\circ}\\)，\\(a=\\sqrt{3}c\\)，\\(b=2\\sqrt{7}\\) 代入，得 \\(28=3c^{2}+c^{2}-2\\times\\sqrt{3}c\\times c\\times\\left(-\\dfrac{\\sqrt{3}}{2}\\right)\\)．\n即 \\(28=4c^{2}+3c^{2}=7c^{2}\\)，解得 \\(c=2\\)（负值舍去），从而 \\(a=2\\sqrt{3}\\)．\n所以 \\(\\triangle ABC\\) 的面积 \\(S=\\dfrac{1}{2}ac\\sin B=\\dfrac{1}{2}\\times2\\sqrt{3}\\times2\\times\\dfrac{1}{2}=\\sqrt{3}\\)．\n\n(2) 由 \\(B=150^{\\circ}\\) 得 \\(A+C=30^{\\circ}\\)，即 \\(A=30^{\\circ}-C\\)，且 \\(0<C<30^{\\circ}\\)．\n所以 \\(\\sin A=\\sin\\left(30^{\\circ}-C\\right)=\\dfrac{1}{2}\\cos C-\\dfrac{\\sqrt{3}}{2}\\sin C\\)．\n代入 \\(\\sin A+\\sqrt{3}\\sin C=\\dfrac{\\sqrt{2}}{2}\\)，得 \\(\\dfrac{1}{2}\\cos C-\\dfrac{\\sqrt{3}}{2}\\sin C+\\sqrt{3}\\sin C=\\dfrac{\\sqrt{2}}{2}\\)．\n即 \\(\\dfrac{1}{2}\\cos C+\\dfrac{\\sqrt{3}}{2}\\sin C=\\dfrac{\\sqrt{2}}{2}\\)，也就是 \\(\\sin\\left(C+30^{\\circ}\\right)=\\dfrac{\\sqrt{2}}{2}\\)．\n由 \\(0<C<30^{\\circ}\\) 得 \\(30^{\\circ}<C+30^{\\circ}<60^{\\circ}\\)，在这个范围内正弦值为 \\(\\dfrac{\\sqrt{2}}{2}\\) 的角只有 \\(45^{\\circ}\\)，故 \\(C+30^{\\circ}=45^{\\circ}\\)．\n所以 \\(C=15^{\\circ}\\)．","scoring":[{"text":"由余弦定理代入得 \\(7c^{2}=28\\)，求出 \\(c=2\\)，\\(a=2\\sqrt{3}\\)","points":4},{"text":"用面积公式求出 \\(S=\\sqrt{3}\\)","points":2},{"text":"由 \\(A+C=30^{\\circ}\\) 写出 \\(\\sin A=\\dfrac{1}{2}\\cos C-\\dfrac{\\sqrt{3}}{2}\\sin C\\) 并代入条件","points":2},{"text":"整理成 \\(\\sin\\left(C+30^{\\circ}\\right)=\\dfrac{\\sqrt{2}}{2}\\)","points":2},{"text":"结合 \\(0<C<30^{\\circ}\\) 求出 \\(C=15^{\\circ}\\)","points":2}]},"triangle-big-021":{"final":"(1) \\(A=\\frac{2\\pi}{3}\\)；(2) \\(\\triangle ABC\\) 周长的最大值为 \\(3+2\\sqrt{3}\\)。","solution":"由正弦定理 \\(\\frac{a}{\\sin A}=\\frac{b}{\\sin B}=\\frac{c}{\\sin C}=2R\\)，可设 \\(a=2R\\sin A\\)，\\(b=2R\\sin B\\)，\\(c=2R\\sin C\\)。\n把条件 \\(\\sin^{2}A-\\sin^{2}B-\\sin^{2}C=\\sin B\\sin C\\) 两边同乘 \\(4R^{2}\\)，得 \\(a^{2}-b^{2}-c^{2}=bc\\)。\n由余弦定理 \\(\\cos A=\\frac{b^{2}+c^{2}-a^{2}}{2bc}=\\frac{-bc}{2bc}=-\\frac{1}{2}\\)。\n因为 \\(A\\in(0,\\pi)\\)，所以 \\(A=\\frac{2\\pi}{3}\\)。\n(2) 已知 \\(BC=a=3\\)，由余弦定理 \\(a^{2}=b^{2}+c^{2}-2bc\\cos A=b^{2}+c^{2}+bc=9\\)。\n于是 \\((b+c)^{2}=b^{2}+c^{2}+2bc=9+bc\\)，问题转化为在 \\(b^{2}+c^{2}+bc=9\\) 的条件下求 \\(b+c\\) 的最大值。\n由基本不等式 \\(bc\\le\\left(\\frac{b+c}{2}\\right)^{2}\\)，代入上式得 \\((b+c)^{2}\\le 9+\\frac{(b+c)^{2}}{4}\\)。\n解得 \\((b+c)^{2}\\le 12\\)，即 \\(b+c\\le 2\\sqrt{3}\\)，等号当且仅当 \\(b=c=\\sqrt{3}\\) 时成立。\n当 \\(b=c=\\sqrt{3}\\) 时 \\(b^{2}+c^{2}+bc=3+3+3=9\\) 成立，且 \\(\\sqrt{3}+\\sqrt{3}>3\\)，确实构成三角形。\n所以周长 \\(a+b+c=3+(b+c)\\le 3+2\\sqrt{3}\\)，即周长的最大值为 \\(3+2\\sqrt{3}\\)。","scoring":[{"text":"用正弦定理把条件化为边的等式 \\(a^{2}-b^{2}-c^{2}=bc\\)","points":3},{"text":"由余弦定理求出 \\(\\cos A=-\\frac{1}{2}\\)，得 \\(A=\\frac{2\\pi}{3}\\)","points":3},{"text":"对 \\(a=3\\) 用余弦定理，得 \\(b^{2}+c^{2}+bc=9\\)","points":2},{"text":"用基本不等式 \\(bc\\le\\left(\\frac{b+c}{2}\\right)^{2}\\) 建立关于 \\(b+c\\) 的不等式","points":2},{"text":"解得 \\(b+c\\le 2\\sqrt{3}\\)，并说明 \\(b=c=\\sqrt{3}\\) 时取到等号","points":1},{"text":"得出周长最大值为 \\(3+2\\sqrt{3}\\)","points":1}]},"triangle-big-022":{"final":"(1) \\(A=\\frac{\\pi}{3}\\)；(2) 由 \\(B=\\frac{\\pi}{2}\\)，\\(C=\\frac{\\pi}{6}\\) 知 \\(\\triangle ABC\\) 是以 \\(B\\) 为直角的直角三角形。","solution":"由诱导公式 \\(\\cos\\left(\\frac{\\pi}{2}+A\\right)=-\\sin A\\)，得 \\(\\cos^{2}\\left(\\frac{\\pi}{2}+A\\right)=\\sin^{2}A=1-\\cos^{2}A\\)。\n条件化为 \\(1-\\cos^{2}A+\\cos A=\\frac{5}{4}\\)，即 \\(\\cos^{2}A-\\cos A+\\frac{1}{4}=0\\)。\n配方得 \\(\\left(\\cos A-\\frac{1}{2}\\right)^{2}=0\\)，故 \\(\\cos A=\\frac{1}{2}\\)。\n因为 \\(A\\in(0,\\pi)\\)，所以 \\(A=\\frac{\\pi}{3}\\)。\n(2) 由正弦定理 \\(\\frac{a}{\\sin A}=\\frac{b}{\\sin B}=\\frac{c}{\\sin C}\\)，条件 \\(b-c=\\frac{\\sqrt{3}}{3}a\\) 化为 \\(\\sin B-\\sin C=\\frac{\\sqrt{3}}{3}\\sin A\\)。\n代入 \\(\\sin A=\\sin\\frac{\\pi}{3}=\\frac{\\sqrt{3}}{2}\\)，得 \\(\\sin B-\\sin C=\\frac{\\sqrt{3}}{3}\\cdot\\frac{\\sqrt{3}}{2}=\\frac{1}{2}\\)。\n又 \\(B+C=\\pi-A=\\frac{2\\pi}{3}\\)，用和差化积得 \\(\\sin B-\\sin C=2\\cos\\frac{B+C}{2}\\sin\\frac{B-C}{2}=2\\cos\\frac{\\pi}{3}\\sin\\frac{B-C}{2}=\\sin\\frac{B-C}{2}\\)。\n所以 \\(\\sin\\frac{B-C}{2}=\\frac{1}{2}\\)。\n由 \\(B,C\\in(0,\\pi)\\) 且 \\(B+C=\\frac{2\\pi}{3}\\)，得 \\(-\\frac{\\pi}{3}<\\frac{B-C}{2}<\\frac{\\pi}{3}\\)，故只能 \\(\\frac{B-C}{2}=\\frac{\\pi}{6}\\)，即 \\(B-C=\\frac{\\pi}{3}\\)。\n与 \\(B+C=\\frac{2\\pi}{3}\\) 联立，解得 \\(B=\\frac{\\pi}{2}\\)，\\(C=\\frac{\\pi}{6}\\)。\n所以 \\(\\triangle ABC\\) 是以 \\(B\\) 为直角的直角三角形。","scoring":[{"text":"用诱导公式把 \\(\\cos\\left(\\frac{\\pi}{2}+A\\right)\\) 化为 \\(-\\sin A\\)，条件变为 \\(\\sin^{2}A+\\cos A=\\frac{5}{4}\\)","points":3},{"text":"整理成 \\(\\left(\\cos A-\\frac{1}{2}\\right)^{2}=0\\)，得 \\(\\cos A=\\frac{1}{2}\\)，从而 \\(A=\\frac{\\pi}{3}\\)","points":3},{"text":"用正弦定理把 \\(b-c=\\frac{\\sqrt{3}}{3}a\\) 化为 \\(\\sin B-\\sin C=\\frac{1}{2}\\)","points":2},{"text":"和差化积得 \\(\\sin\\frac{B-C}{2}=\\frac{1}{2}\\)，结合范围得 \\(B-C=\\frac{\\pi}{3}\\)","points":2},{"text":"与 \\(B+C=\\frac{2\\pi}{3}\\) 联立求出 \\(B=\\frac{\\pi}{2}\\)","points":1},{"text":"结论：\\(\\triangle ABC\\) 是直角三角形","points":1}]},"triangle-big-024":{"final":"选①：\\(c=1\\)，三角形存在；选②：\\(c=2\\sqrt{3}\\)，三角形存在；选③：三角形不存在（三个条件都补充在 \\(\\sin A=\\sqrt{3}\\sin B\\)，\\(C=\\frac{\\pi}{6}\\) 之下）。","solution":"三个条件都补充在“\\(\\sin A=\\sqrt{3}\\sin B\\)，\\(C=\\frac{\\pi}{6}\\)”之下，先由共同条件确定三角形的形状。\n由正弦定理 \\(\\sin A=\\sqrt{3}\\sin B\\) 得 \\(a=\\sqrt{3}b\\)。\n由余弦定理 \\(c^{2}=a^{2}+b^{2}-2ab\\cos C=3b^{2}+b^{2}-2\\cdot\\sqrt{3}b^{2}\\cdot\\frac{\\sqrt{3}}{2}=4b^{2}-3b^{2}=b^{2}\\)，故 \\(c=b\\)。\n此时 \\(\\cos A=\\frac{b^{2}+c^{2}-a^{2}}{2bc}=\\frac{b^{2}+b^{2}-3b^{2}}{2b^{2}}=-\\frac{1}{2}\\)，即 \\(A=\\frac{2\\pi}{3}\\)，于是 \\(B=C=\\frac{\\pi}{6}\\)，三边比为 \\(a:b:c=\\sqrt{3}:1:1\\)。\n若选①\\(ac=\\sqrt{3}\\)：把 \\(a=\\sqrt{3}b\\)，\\(c=b\\) 代入得 \\(ac=\\sqrt{3}b^{2}=\\sqrt{3}\\)，所以 \\(b=1\\)，\\(c=1\\)，\\(a=\\sqrt{3}\\)。\n验证：\\(\\sqrt{3}<1+1\\)，且 \\(\\cos C=\\frac{a^{2}+b^{2}-c^{2}}{2ab}=\\frac{3+1-1}{2\\sqrt{3}}=\\frac{\\sqrt{3}}{2}\\)，即 \\(C=\\frac{\\pi}{6}\\)，与题设相符。\n所以选①时三角形存在，\\(c=1\\)。\n若选②\\(c\\sin A=3\\)：由 \\(A=\\frac{2\\pi}{3}\\) 得 \\(\\sin A=\\frac{\\sqrt{3}}{2}\\)，所以 \\(c\\cdot\\frac{\\sqrt{3}}{2}=3\\)，即 \\(c=2\\sqrt{3}\\)。\n此时 \\(b=c=2\\sqrt{3}\\)，\\(a=\\sqrt{3}b=6\\)，验证 \\(6<2\\sqrt{3}+2\\sqrt{3}=4\\sqrt{3}\\)，三角形存在。\n所以选②时三角形存在，\\(c=2\\sqrt{3}\\)。\n若选③\\(c=\\sqrt{3}b\\)：与 \\(c=b\\) 且 \\(b>0\\) 矛盾，故这样的三角形不存在。","scoring":[{"text":"由 \\(\\sin A=\\sqrt{3}\\sin B\\) 及正弦定理得 \\(a=\\sqrt{3}b\\)","points":2},{"text":"由余弦定理得 \\(c=b\\)，并进一步得出 \\(A=\\frac{2\\pi}{3}\\)，\\(B=C=\\frac{\\pi}{6}\\)","points":3},{"text":"选①：由 \\(ac=\\sqrt{3}\\) 结合 \\(a=\\sqrt{3}b\\)，\\(c=b\\) 求得 \\(b=c=1\\)、\\(a=\\sqrt{3}\\)，并验证存在，得 \\(c=1\\)","points":3},{"text":"选②：由 \\(\\sin A=\\frac{\\sqrt{3}}{2}\\) 代入 \\(c\\sin A=3\\) 得 \\(c=2\\sqrt{3}\\)，并验证存在","points":3},{"text":"选③：指出 \\(c=\\sqrt{3}b\\) 与 \\(c=b\\) 矛盾，三角形不存在","points":1}]},"triangle-big-025":{"final":"选条件①：\\(a=8\\)，\\(\\sin C=\\frac{\\sqrt{3}}{2}\\)，\\(S_{\\triangle ABC}=6\\sqrt{3}\\)；选条件②：\\(a=6\\)，\\(\\sin C=\\frac{\\sqrt{7}}{4}\\)，\\(S_{\\triangle ABC}=\\frac{15\\sqrt{7}}{4}\\)。","solution":"若选条件①：由余弦定理 \\(\\cos A=\\frac{b^{2}+c^{2}-a^{2}}{2bc}=-\\frac{1}{7}\\)，其中 \\(c=7\\)，\\(b=11-a\\)。\n代入得 \\(\\frac{(11-a)^{2}+49-a^{2}}{14(11-a)}=-\\frac{1}{7}\\)，即 \\((11-a)^{2}+49-a^{2}=-2(11-a)\\)。\n展开得 \\(121-22a+a^{2}+49-a^{2}=-22+2a\\)，即 \\(170-22a=-22+2a\\)，解得 \\(a=8\\)。\n此时 \\(b=3\\)，且 \\(b+c=10>a=8\\)，三角形存在。\n因为 \\(\\cos A<0\\)，\\(A\\) 为钝角，所以 \\(\\sin A=\\sqrt{1-\\left(-\\frac{1}{7}\\right)^{2}}=\\frac{4\\sqrt{3}}{7}\\)。\n由正弦定理 \\(\\sin C=\\frac{c\\sin A}{a}=\\frac{7}{8}\\cdot\\frac{4\\sqrt{3}}{7}=\\frac{\\sqrt{3}}{2}\\)。\n由于 \\(A\\) 为钝角，\\(C\\) 只能是锐角，故 \\(C=\\frac{\\pi}{3}\\)（否则 \\(C=\\frac{2\\pi}{3}\\) 与 \\(A+C<\\pi\\) 矛盾）。\n面积 \\(S=\\frac{1}{2}ab\\sin C=\\frac{1}{2}\\cdot 8\\cdot 3\\cdot\\frac{\\sqrt{3}}{2}=6\\sqrt{3}\\)。\n若选条件②：由 \\(\\cos A=\\frac{1}{8}\\)，\\(\\cos B=\\frac{9}{16}\\)，得 \\(\\sin A=\\sqrt{1-\\frac{1}{64}}=\\frac{3\\sqrt{7}}{8}\\)，\\(\\sin B=\\sqrt{1-\\frac{81}{256}}=\\frac{5\\sqrt{7}}{16}\\)。\n由正弦定理 \\(\\frac{a}{b}=\\frac{\\sin A}{\\sin B}=\\frac{3\\sqrt{7}/8}{5\\sqrt{7}/16}=\\frac{6}{5}\\)。\n设 \\(a=6k\\)，\\(b=5k\\)，由 \\(a+b=11\\) 得 \\(11k=11\\)，即 \\(k=1\\)，所以 \\(a=6\\)，\\(b=5\\)。\n\\(\\sin C=\\sin(A+B)=\\sin A\\cos B+\\cos A\\sin B=\\frac{3\\sqrt{7}}{8}\\cdot\\frac{9}{16}+\\frac{1}{8}\\cdot\\frac{5\\sqrt{7}}{16}=\\frac{27\\sqrt{7}+5\\sqrt{7}}{128}=\\frac{\\sqrt{7}}{4}\\)。\n面积 \\(S=\\frac{1}{2}ab\\sin C=\\frac{1}{2}\\cdot 6\\cdot 5\\cdot\\frac{\\sqrt{7}}{4}=\\frac{15\\sqrt{7}}{4}\\)。","scoring":[{"text":"选①：由余弦定理并结合 \\(b=11-a\\) 建立方程，解得 \\(a=8\\)（此时 \\(b=3\\)）","points":4},{"text":"选①：由 \\(\\cos A=-\\frac{1}{7}\\) 求 \\(\\sin A=\\frac{4\\sqrt{3}}{7}\\)，再用正弦定理得 \\(\\sin C=\\frac{\\sqrt{3}}{2}\\)","points":3},{"text":"选①：由 \\(S=\\frac{1}{2}ab\\sin C\\) 得面积 \\(6\\sqrt{3}\\)","points":2},{"text":"选②：由正弦定理得 \\(a:b=6:5\\)，结合 \\(a+b=11\\) 得 \\(a=6\\)，\\(b=5\\)","points":2},{"text":"选②：用 \\(\\sin C=\\sin(A+B)\\) 得 \\(\\sin C=\\frac{\\sqrt{7}}{4}\\)，并得面积 \\(\\frac{15\\sqrt{7}}{4}\\)","points":1}]},"triangle-big-026":{"final":"(Ⅰ) \\(C=\\frac{\\pi}{4}\\)；(Ⅱ) \\(\\sin A=\\frac{2\\sqrt{13}}{13}\\)；(Ⅲ) \\(\\sin\\left(2A+\\frac{\\pi}{4}\\right)=\\frac{17\\sqrt{2}}{26}\\)。","solution":"(Ⅰ) 由余弦定理 \\(\\cos C=\\frac{a^{2}+b^{2}-c^{2}}{2ab}=\\frac{8+25-13}{2\\cdot 2\\sqrt{2}\\cdot 5}=\\frac{20}{20\\sqrt{2}}=\\frac{\\sqrt{2}}{2}\\)。\n因为 \\(C\\in(0,\\pi)\\)，所以 \\(C=\\frac{\\pi}{4}\\)。\n(Ⅱ) 由正弦定理 \\(\\frac{a}{\\sin A}=\\frac{c}{\\sin C}\\)，得 \\(\\sin A=\\frac{a\\sin C}{c}=\\frac{2\\sqrt{2}\\cdot\\frac{\\sqrt{2}}{2}}{\\sqrt{13}}=\\frac{2}{\\sqrt{13}}=\\frac{2\\sqrt{13}}{13}\\)。\n(Ⅲ) 因为 \\(a=2\\sqrt{2}<c=\\sqrt{13}\\)，所以 \\(A<C=\\frac{\\pi}{4}\\)，即 \\(A\\) 为锐角，\\(\\cos A=\\sqrt{1-\\frac{4}{13}}=\\frac{3}{\\sqrt{13}}=\\frac{3\\sqrt{13}}{13}\\)。\n于是 \\(\\sin 2A=2\\sin A\\cos A=2\\cdot\\frac{2}{\\sqrt{13}}\\cdot\\frac{3}{\\sqrt{13}}=\\frac{12}{13}\\)。\n\\(\\cos 2A=1-2\\sin^{2}A=1-\\frac{8}{13}=\\frac{5}{13}\\)。\n所以 \\(\\sin\\left(2A+\\frac{\\pi}{4}\\right)=\\sin 2A\\cos\\frac{\\pi}{4}+\\cos 2A\\sin\\frac{\\pi}{4}=\\frac{\\sqrt{2}}{2}\\left(\\frac{12}{13}+\\frac{5}{13}\\right)=\\frac{17\\sqrt{2}}{26}\\)。","scoring":[{"text":"由余弦定理求 \\(\\cos C=\\frac{\\sqrt{2}}{2}\\)，得 \\(C=\\frac{\\pi}{4}\\)","points":4},{"text":"由正弦定理求 \\(\\sin A=\\frac{2\\sqrt{13}}{13}\\)","points":3},{"text":"由 \\(a<c\\) 判断 \\(A\\) 为锐角，求得 \\(\\cos A=\\frac{3\\sqrt{13}}{13}\\)","points":2},{"text":"用二倍角公式求 \\(\\sin 2A=\\frac{12}{13}\\)，\\(\\cos 2A=\\frac{5}{13}\\)","points":2},{"text":"用两角和公式求得 \\(\\sin\\left(2A+\\frac{\\pi}{4}\\right)=\\frac{17\\sqrt{2}}{26}\\)","points":1}]},"triangle-big-027":{"final":"(Ⅰ) \\(B=\\frac{\\pi}{3}\\)；(Ⅱ) \\(\\cos A+\\cos B+\\cos C\\in\\left(\\frac{\\sqrt{3}+1}{2},\\frac{3}{2}\\right]\\)。","solution":"(Ⅰ) 由正弦定理，\\(2b\\sin A=\\sqrt{3}a\\) 化为 \\(2\\sin B\\sin A=\\sqrt{3}\\sin A\\)。\n因为 \\(A\\in(0,\\pi)\\)，\\(\\sin A\\neq 0\\)，所以 \\(\\sin B=\\frac{\\sqrt{3}}{2}\\)。\n又 \\(\\triangle ABC\\) 为锐角三角形，\\(B\\in\\left(0,\\frac{\\pi}{2}\\right)\\)，故 \\(B=\\frac{\\pi}{3}\\)。\n(Ⅱ) 由 \\(A+B+C=\\pi\\) 得 \\(A+C=\\frac{2\\pi}{3}\\)，即 \\(C=\\frac{2\\pi}{3}-A\\)。\n用和差化积 \\(\\cos A+\\cos C=2\\cos\\frac{A+C}{2}\\cos\\frac{A-C}{2}=2\\cos\\frac{\\pi}{3}\\cos\\frac{A-C}{2}=\\cos\\frac{A-C}{2}\\)。\n而 \\(\\frac{A-C}{2}=\\frac{A-\\left(\\frac{2\\pi}{3}-A\\right)}{2}=A-\\frac{\\pi}{3}\\)，所以 \\(\\cos A+\\cos C=\\cos\\left(A-\\frac{\\pi}{3}\\right)\\)。\n于是 \\(\\cos A+\\cos B+\\cos C=\\cos\\left(A-\\frac{\\pi}{3}\\right)+\\frac{1}{2}\\)。\n锐角三角形要求 \\(0<A<\\frac{\\pi}{2}\\) 且 \\(0<C=\\frac{2\\pi}{3}-A<\\frac{\\pi}{2}\\)，解得 \\(\\frac{\\pi}{6}<A<\\frac{\\pi}{2}\\)。\n所以 \\(A-\\frac{\\pi}{3}\\in\\left(-\\frac{\\pi}{6},\\frac{\\pi}{6}\\right)\\)，从而 \\(\\cos\\left(A-\\frac{\\pi}{3}\\right)\\in\\left(\\frac{\\sqrt{3}}{2},1\\right]\\)。\n当 \\(A=\\frac{\\pi}{3}\\) 时 \\(\\cos\\left(A-\\frac{\\pi}{3}\\right)=1\\)，可以取到最大值；\n而 \\(\\cos\\left(A-\\frac{\\pi}{3}\\right)=\\frac{\\sqrt{3}}{2}\\) 需 \\(A=\\frac{\\pi}{6}\\) 或 \\(A=\\frac{\\pi}{2}\\)，这两种情形分别使 \\(C=\\frac{\\pi}{2}\\)、\\(A=\\frac{\\pi}{2}\\)，都不是锐角三角形，故取不到。\n所以 \\(\\cos A+\\cos B+\\cos C\\in\\left(\\frac{\\sqrt{3}}{2}+\\frac{1}{2},\\frac{3}{2}\\right]\\)，即 \\(\\left(\\frac{\\sqrt{3}+1}{2},\\frac{3}{2}\\right]\\)。","scoring":[{"text":"用正弦定理把 \\(2b\\sin A=\\sqrt{3}a\\) 化为 \\(2\\sin B\\sin A=\\sqrt{3}\\sin A\\)","points":3},{"text":"由 \\(\\sin A\\neq 0\\) 得 \\(\\sin B=\\frac{\\sqrt{3}}{2}\\)，结合锐角条件得 \\(B=\\frac{\\pi}{3}\\)","points":3},{"text":"用和差化积把 \\(\\cos A+\\cos C\\) 化为 \\(\\cos\\left(A-\\frac{\\pi}{3}\\right)\\)，得原式 \\(=\\cos\\left(A-\\frac{\\pi}{3}\\right)+\\frac{1}{2}\\)","points":3},{"text":"由锐角条件确定 \\(\\frac{\\pi}{6}<A<\\frac{\\pi}{2}\\)，得 \\(\\cos\\left(A-\\frac{\\pi}{3}\\right)\\in\\left(\\frac{\\sqrt{3}}{2},1\\right]\\)","points":2},{"text":"得出取值范围 \\(\\left(\\frac{\\sqrt{3}+1}{2},\\frac{3}{2}\\right]\\)，并说明左端点取不到","points":1}]},"triangle-big-028":{"final":"(1) \\(\\sin C=\\frac{\\sqrt{5}}{5}\\)；(2) \\(\\tan\\angle BAD=-7\\)（此时 \\(\\angle BAD\\) 为钝角）。","solution":"(1) 由余弦定理 \\(b^{2}=a^{2}+c^{2}-2ac\\cos B=9+2-2\\cdot 3\\cdot\\sqrt{2}\\cdot\\frac{\\sqrt{2}}{2}=11-6=5\\)，所以 \\(b=\\sqrt{5}\\)。\n由正弦定理 \\(\\frac{c}{\\sin C}=\\frac{b}{\\sin B}\\)，得 \\(\\sin C=\\frac{c\\sin B}{b}=\\frac{\\sqrt{2}\\cdot\\frac{\\sqrt{2}}{2}}{\\sqrt{5}}=\\frac{1}{\\sqrt{5}}=\\frac{\\sqrt{5}}{5}\\)。\n(2) 因为 \\(D\\) 在边 \\(BC\\) 上，所以 \\(\\angle ADB+\\angle ADC=\\pi\\)。\n由 \\(\\cos\\angle ADC=-\\frac{4}{5}\\) 得 \\(\\sin\\angle ADC=\\frac{3}{5}\\)，于是 \\(\\cos\\angle ADB=-\\cos\\angle ADC=\\frac{4}{5}\\)，\\(\\sin\\angle ADB=\\frac{3}{5}\\)，故 \\(\\tan\\angle ADB=\\frac{3}{4}\\)。\n在 \\(\\triangle ABD\\) 中，\\(\\angle ABD=B=\\frac{\\pi}{4}\\)，所以 \\(\\angle BAD=\\pi-\\frac{\\pi}{4}-\\angle ADB=\\frac{3\\pi}{4}-\\angle ADB\\)。\n用两角差的正切公式得 \\(\\tan\\angle BAD=\\tan\\left(\\frac{3\\pi}{4}-\\angle ADB\\right)=\\frac{\\tan\\frac{3\\pi}{4}-\\tan\\angle ADB}{1+\\tan\\frac{3\\pi}{4}\\tan\\angle ADB}=\\frac{-1-\\frac{3}{4}}{1+(-1)\\cdot\\frac{3}{4}}=\\frac{-\\frac{7}{4}}{\\frac{1}{4}}=-7\\)。\n由 \\(\\tan\\angle ADB=\\frac{3}{4}<1\\) 知 \\(\\angle ADB<\\frac{\\pi}{4}\\)，所以 \\(\\angle BAD=\\frac{3\\pi}{4}-\\angle ADB>\\frac{\\pi}{2}\\)，即 \\(\\angle BAD\\) 为钝角，其正切取负值与所得结果一致。","scoring":[{"text":"由余弦定理求 \\(b^{2}=5\\)，即 \\(b=\\sqrt{5}\\)","points":3},{"text":"由正弦定理求 \\(\\sin C=\\frac{\\sqrt{5}}{5}\\)","points":3},{"text":"由 \\(\\cos\\angle ADC=-\\frac{4}{5}\\) 及 \\(\\angle ADB=\\pi-\\angle ADC\\) 得 \\(\\tan\\angle ADB=\\frac{3}{4}\\)","points":3},{"text":"在 \\(\\triangle ABD\\) 中由内角和得 \\(\\angle BAD=\\frac{3\\pi}{4}-\\angle ADB\\)，并用两角差正切公式代入","points":2},{"text":"算出 \\(\\tan\\angle BAD=-7\\)，并说明 \\(\\angle BAD\\) 为钝角","points":1}]},"triangle-big-029":{"final":"(1) \\(BD=b\\)，证明见解析；(2) \\(\\cos\\angle ABC=\\frac{7}{12}\\)。","solution":"(1) 在 \\(\\triangle ABC\\) 中，由正弦定理 \\(\\frac{c}{\\sin C}=\\frac{b}{\\sin B}\\)（其中 \\(B=\\angle ABC\\)）得 \\(\\sin C=\\frac{c\\sin B}{b}\\)。\n所以 \\(a\\sin C=a\\cdot\\frac{c\\sin B}{b}=\\frac{ac}{b}\\sin B\\)。\n由已知 \\(b^{2}=ac\\) 得 \\(\\frac{ac}{b}=b\\)，所以 \\(a\\sin C=b\\sin B\\)。\n代入条件 \\(BD\\sin\\angle ABC=a\\sin C\\)，得 \\(BD\\sin B=b\\sin B\\)。\n因为 \\(B\\in(0,\\pi)\\)，\\(\\sin B\\neq 0\\)，所以 \\(BD=b\\)。\n(2) 由 \\(AD=2DC\\) 及 \\(AC=b\\) 得 \\(DC=\\frac{b}{3}\\)，\\(AD=\\frac{2b}{3}\\)。\n设 \\(\\angle BDC=\\theta\\)，因为 \\(A,D,C\\) 三点共线，所以 \\(\\angle BDA=\\pi-\\theta\\)。\n在 \\(\\triangle BCD\\) 中，由余弦定理 \\(a^{2}=BD^{2}+DC^{2}-2\\cdot BD\\cdot DC\\cos\\theta=b^{2}+\\frac{b^{2}}{9}-\\frac{2b^{2}}{3}\\cos\\theta\\)。\n在 \\(\\triangle ABD\\) 中，由余弦定理 \\(c^{2}=BD^{2}+AD^{2}-2\\cdot BD\\cdot AD\\cos(\\pi-\\theta)=b^{2}+\\frac{4b^{2}}{9}+\\frac{4b^{2}}{3}\\cos\\theta\\)。\n记 \\(x=\\cos\\theta\\)，则 \\(a^{2}=b^{2}\\left(\\frac{10}{9}-\\frac{2}{3}x\\right)\\)，\\(c^{2}=b^{2}\\left(\\frac{13}{9}+\\frac{4}{3}x\\right)\\)。\n由 \\(b^{2}=ac\\) 得 \\(a^{2}c^{2}=b^{4}\\)，即 \\(\\left(\\frac{10}{9}-\\frac{2}{3}x\\right)\\left(\\frac{13}{9}+\\frac{4}{3}x\\right)=1\\)。\n展开得 \\(\\frac{130}{81}+\\frac{40}{27}x-\\frac{26}{27}x-\\frac{8}{9}x^{2}=1\\)，即 \\(\\frac{130}{81}+\\frac{14}{27}x-\\frac{8}{9}x^{2}=1\\)。\n两边同乘 \\(81\\)，得 \\(130+42x-72x^{2}=81\\)，即 \\(72x^{2}-42x-49=0\\)。\n解得 \\(x=\\frac{42\\pm\\sqrt{1764+14112}}{144}=\\frac{42\\pm 126}{144}\\)，即 \\(x=\\frac{7}{6}\\) 或 \\(x=-\\frac{7}{12}\\)。\n因为 \\(x=\\cos\\theta\\in(-1,1)\\)，舍去 \\(\\frac{7}{6}\\)，所以 \\(\\cos\\theta=-\\frac{7}{12}\\)。\n于是 \\(a^{2}=b^{2}\\left(\\frac{10}{9}+\\frac{7}{18}\\right)=\\frac{3}{2}b^{2}\\)，\\(c^{2}=b^{2}\\left(\\frac{13}{9}-\\frac{7}{9}\\right)=\\frac{2}{3}b^{2}\\)，且 \\(a^{2}c^{2}=b^{4}\\) 确实成立。\n所以 \\(\\cos\\angle ABC=\\frac{a^{2}+c^{2}-b^{2}}{2ac}=\\frac{\\frac{3}{2}b^{2}+\\frac{2}{3}b^{2}-b^{2}}{2b^{2}}=\\frac{\\frac{7}{6}}{2}=\\frac{7}{12}\\)。","scoring":[{"text":"用正弦定理把 \\(\\sin C\\) 用 \\(\\sin B\\) 表示，并结合 \\(b^{2}=ac\\) 把 \\(a\\sin C\\) 化为 \\(b\\sin B\\)","points":4},{"text":"由 \\(BD\\sin B=b\\sin B\\) 且 \\(\\sin B\\neq 0\\) 得 \\(BD=b\\)","points":2},{"text":"设 \\(\\angle BDC=\\theta\\)，在两个三角形中分别用余弦定理表示 \\(a^{2}\\) 与 \\(c^{2}\\)","points":3},{"text":"用 \\(a^{2}c^{2}=b^{4}\\) 得到关于 \\(\\cos\\theta\\) 的方程，解得 \\(\\cos\\theta=-\\frac{7}{12}\\)（舍去 \\(\\frac{7}{6}\\)）","points":2},{"text":"求出 \\(a^{2}=\\frac{3}{2}b^{2}\\)、\\(c^{2}=\\frac{2}{3}b^{2}\\)，得 \\(\\cos\\angle ABC=\\frac{7}{12}\\)","points":1}]},"triangle-big-030":{"final":"(1) \\(S_{\\triangle ABC}=\\frac{15\\sqrt{7}}{4}\\)；(2) 存在，且 \\(a=2\\) 是唯一满足条件的正整数。","solution":"(1) 由正弦定理，\\(2\\sin C=3\\sin A\\) 化为 \\(2c=3a\\)。\n代入 \\(c=a+2\\) 得 \\(2(a+2)=3a\\)，解得 \\(a=4\\)，于是 \\(b=5\\)，\\(c=6\\)。\n由余弦定理 \\(\\cos C=\\frac{a^{2}+b^{2}-c^{2}}{2ab}=\\frac{16+25-36}{40}=\\frac{1}{8}\\)，所以 \\(\\sin C=\\sqrt{1-\\frac{1}{64}}=\\frac{3\\sqrt{7}}{8}\\)。\n面积 \\(S=\\frac{1}{2}ab\\sin C=\\frac{1}{2}\\cdot 4\\cdot 5\\cdot\\frac{3\\sqrt{7}}{8}=\\frac{15\\sqrt{7}}{4}\\)。\n(2) 因为 \\(c=a+2\\) 是三边中最大的，所以 \\(C\\) 是最大角，\\(\\triangle ABC\\) 为钝角三角形等价于 \\(C\\) 为钝角，即 \\(\\cos C<0\\)，等价于 \\(a^{2}+b^{2}<c^{2}\\)。\n代入 \\(b=a+1\\)，\\(c=a+2\\)，得 \\(a^{2}+(a+1)^{2}<(a+2)^{2}\\)，即 \\(2a^{2}+2a+1<a^{2}+4a+4\\)。\n整理得 \\(a^{2}-2a-3<0\\)，即 \\((a-3)(a+1)<0\\)，解得 \\(-1<a<3\\)。\n又 \\(a\\) 为正整数，故 \\(a=1\\) 或 \\(a=2\\)。\n还要满足三角形不等式 \\(a+b>c\\)，即 \\(a+(a+1)>a+2\\)，得 \\(a>1\\)。\n所以只有 \\(a=2\\) 可能。\n检验：当 \\(a=2\\) 时三边为 \\(2,3,4\\)，满足 \\(2+3>4\\)，且 \\(\\cos C=\\frac{4+9-16}{2\\cdot 2\\cdot 3}=-\\frac{1}{4}<0\\)，确实是钝角三角形。\n所以存在正整数 \\(a=2\\)，且由上面的讨论知它是唯一的。","scoring":[{"text":"由正弦定理把 \\(2\\sin C=3\\sin A\\) 化为 \\(2c=3a\\)，结合 \\(c=a+2\\) 解得 \\(a=4\\)","points":3},{"text":"由余弦定理求 \\(\\cos C=\\frac{1}{8}\\)，进而得 \\(\\sin C=\\frac{3\\sqrt{7}}{8}\\)","points":3},{"text":"由 \\(S=\\frac{1}{2}ab\\sin C\\) 求得面积 \\(\\frac{15\\sqrt{7}}{4}\\)","points":2},{"text":"判断只需最大角 \\(C\\) 为钝角，由 \\(a^{2}+b^{2}<c^{2}\\) 得 \\(a^{2}-2a-3<0\\)，即 \\(-1<a<3\\)","points":2},{"text":"结合三角形不等式 \\(a+b>c\\) 得 \\(a=2\\)，并验证其为钝角三角形","points":2}]},"triangle-big-031":{"final":"(1) \\(B=\\frac{\\pi}{6}\\)；(2) 条件①不能使三角形存在；选②得 \\(BC\\) 边上的中线长为 \\(\\sqrt{7}\\)，选③得 \\(BC\\) 边上的中线长为 \\(\\frac{\\sqrt{21}}{2}\\)。","solution":"(1) 由正弦定理，\\(c=2b\\cos B\\) 化为 \\(\\sin C=2\\sin B\\cos B=\\sin 2B\\)。\n又 \\(C=\\frac{2\\pi}{3}\\)，\\(\\sin C=\\sin\\frac{2\\pi}{3}=\\frac{\\sqrt{3}}{2}\\)，所以 \\(\\sin 2B=\\frac{\\sqrt{3}}{2}\\)。\n因为 \\(A+B=\\pi-C=\\frac{\\pi}{3}\\)，所以 \\(B\\in\\left(0,\\frac{\\pi}{3}\\right)\\)，从而 \\(2B\\in\\left(0,\\frac{2\\pi}{3}\\right)\\)。\n故 \\(2B=\\frac{\\pi}{3}\\)，即 \\(B=\\frac{\\pi}{6}\\)。\n若 \\(2B=\\frac{2\\pi}{3}\\)，则 \\(B=\\frac{\\pi}{3}\\)，此时 \\(A=\\pi-\\frac{2\\pi}{3}-\\frac{\\pi}{3}=0\\)，不能构成三角形，故舍去。\n此时 \\(A=\\pi-\\frac{2\\pi}{3}-\\frac{\\pi}{6}=\\frac{\\pi}{6}=B\\)，所以 \\(a=b\\)。\n再由 \\(c=2b\\cos B=2b\\cdot\\frac{\\sqrt{3}}{2}=\\sqrt{3}b\\)，即三边满足 \\(c=\\sqrt{3}a\\)。\n(2) ① 若 \\(c=\\sqrt{2}b\\)，与 \\(c=\\sqrt{3}b\\) 矛盾，所以这样的三角形不存在。\n② 若周长为 \\(4+2\\sqrt{3}\\)：由 \\(a+b+c=2a+\\sqrt{3}a=(2+\\sqrt{3})a=4+2\\sqrt{3}\\)，解得 \\(a=\\frac{4+2\\sqrt{3}}{2+\\sqrt{3}}=\\frac{(4+2\\sqrt{3})(2-\\sqrt{3})}{(2+\\sqrt{3})(2-\\sqrt{3})}=2\\)，即 \\(a=b=2\\)，\\(c=2\\sqrt{3}\\)，三角形三边被唯一确定且满足三角形不等式。\n设 \\(M\\) 为 \\(BC\\) 的中点，则 \\(AM\\) 就是 \\(BC\\) 边上的中线，由中线长公式得 \\(AM^{2}=\\frac{2b^{2}+2c^{2}-a^{2}}{4}=\\frac{2\\cdot 4+2\\cdot 12-4}{4}=7\\)，所以 \\(AM=\\sqrt{7}\\)。\n③ 若 \\(S_{\\triangle ABC}=\\frac{3\\sqrt{3}}{4}\\)：由 \\(S=\\frac{1}{2}ab\\sin C=\\frac{1}{2}a^{2}\\cdot\\frac{\\sqrt{3}}{2}=\\frac{\\sqrt{3}}{4}a^{2}=\\frac{3\\sqrt{3}}{4}\\) 得 \\(a^{2}=3\\)，即 \\(a=\\sqrt{3}\\)。\n此时 \\(a=b=\\sqrt{3}\\)，\\(c=3\\)，同样被唯一确定，由中线长公式得 \\(AM^{2}=\\frac{2b^{2}+2c^{2}-a^{2}}{4}=\\frac{2\\cdot 3+2\\cdot 9-3}{4}=\\frac{21}{4}\\)，所以 \\(AM=\\frac{\\sqrt{21}}{2}\\)。\n综上，条件①不能使三角形存在，条件②与条件③都能使命题中的三角形存在且唯一确定。","scoring":[{"text":"用正弦定理及二倍角公式把 \\(c=2b\\cos B\\) 化为 \\(\\sin C=\\sin 2B\\)","points":3},{"text":"由 \\(C=\\frac{2\\pi}{3}\\) 及 \\(B\\in\\left(0,\\frac{\\pi}{3}\\right)\\) 求出 \\(B=\\frac{\\pi}{6}\\)，并舍去 \\(B=\\frac{\\pi}{3}\\)","points":3},{"text":"推出 \\(a=b\\)，\\(c=\\sqrt{3}b\\)，指出 ① 中 \\(c=\\sqrt{2}b\\) 与 \\(c=\\sqrt{3}b\\) 矛盾，三角形不存在","points":2},{"text":"选②：由周长条件求出 \\(a=b=2\\)，\\(c=2\\sqrt{3}\\)","points":1},{"text":"用中线长公式求出中线长（选②得 \\(\\sqrt{7}\\)，选③得 \\(\\frac{\\sqrt{21}}{2}\\)）","points":3}]}});
